function _sajuPromptBindCalibrationSection(rootEl) {
  var section = rootEl && rootEl.querySelector('[data-saju-ai-calib]');
  if (!section) return;
  var rowsEl = section.querySelector('[data-saju-ai-calib-rows]');
  var addBtn = section.querySelector('[data-saju-ai-calib-add]');
  var nudgeEl = section.querySelector('[data-saju-ai-calib-nudge]');
  if (!rowsEl || !addBtn) return;
  function updateNudge() {
    if (!nudgeEl) return;
    var collected = _sajuPromptCollectCalibration(section);
    var periods = collected ? collected.periods : [];
    var good = periods.filter(function(p) { return p.polarity === 'good'; }).length;
    var bad = periods.length - good;
    var message;
    if (!periods.length) message = '한 시기만 알려줘도 보정이 시작돼요';
    else if (!good || !bad) message = '좋았던 시기와 힘들었던 시기를 하나씩 채우면 정확도 보정이 켜져요';
    else if (good === 1 && bad === 1) message = '하나만 더 알려주시면 훨씬 정확해져요 (2~3개 권장)';
    else message = '시기 ' + periods.length + '건이 상담 보정에 반영돼요';
    nudgeEl.textContent = message;
  }
  function fillRow(row, period) {
    if (!row || !period) return;
    var polarityEl = row.querySelector('[data-saju-ai-calib-polarity]');
    var whenEl = row.querySelector('[data-saju-ai-calib-when]');
    var areaEl = row.querySelector('[data-saju-ai-calib-area]');
    var intensityEl = row.querySelector('[data-saju-ai-calib-intensity]');
    var noteEl = row.querySelector('[data-saju-ai-calib-note]');
    if (polarityEl) polarityEl.value = period.polarity === 'bad' ? 'bad' : 'good';
    if (whenEl) whenEl.value = period.year ? String(period.year) : (period.age ? String(period.age) : '');
    if (areaEl && period.area) areaEl.value = period.area;
    if (intensityEl && period.intensity) intensityEl.value = String(period.intensity);
    if (noteEl) noteEl.value = String(period.note || '');
  }
  function syncAddButton() {
    var count = rowsEl.querySelectorAll('[data-saju-ai-calib-row]').length;
    var full = count >= _SAJU_CALIB_MAX_ROWS;
    addBtn.disabled = full;
    addBtn.style.opacity = full ? '0.6' : '1';
  }
  var saved = _sajuPromptReadSavedCalibration();
  if (saved && Array.isArray(saved.periods) && saved.periods.length) {
    var needed = Math.min(_SAJU_CALIB_MAX_ROWS, saved.periods.length);
    while (rowsEl.querySelectorAll('[data-saju-ai-calib-row]').length < needed) {
      rowsEl.insertAdjacentHTML('beforeend', _sajuPromptBuildCalibRowHtml('good'));
    }
    var rows = rowsEl.querySelectorAll('[data-saju-ai-calib-row]');
    saved.periods.slice(0, needed).forEach(function(period, idx) { fillRow(rows[idx], period); });
    section.open = true;
  }
  addBtn.addEventListener('click', function() {
    var count = rowsEl.querySelectorAll('[data-saju-ai-calib-row]').length;
    if (count >= _SAJU_CALIB_MAX_ROWS) return;
    rowsEl.insertAdjacentHTML('beforeend', _sajuPromptBuildCalibRowHtml(count % 2 === 0 ? 'good' : 'bad'));
    syncAddButton();
    updateNudge();
  });
  section.addEventListener('input', updateNudge);
  section.addEventListener('change', updateNudge);
  syncAddButton();
  updateNudge();
}

function _confirmSajuQuestionPromptPurchase(domain, privacyOptions, calibrationCount) {
  if (typeof window.confirm !== 'function') return true;
  var protectedItems = [];
  if (privacyOptions && privacyOptions.hideName) protectedItems.push('이름 원문');
  if (privacyOptions && privacyOptions.hideBirth) protectedItems.push('원본 생년월일');
  if (privacyOptions && privacyOptions.hideTime) protectedItems.push('원본 출생시간');
  var protectedText = protectedItems.length ? protectedItems.join(', ') + ' 제외' : '개인정보 원문 포함';
  var calibrationText = Number(calibrationCount) > 0 ? '정확도 보정: 시기 ' + Number(calibrationCount) + '건 반영\n' : '';
  return window.confirm(
    '사주 AI 상담 결과를 엽니다. 결제, 월정석 크레딧, 멤버십 이용권 중 사용 가능한 방식으로 확인됩니다.\n\n'
    + '선택 주제: ' + _sajuPromptDomainLabel(domain) + '\n'
    + '개인정보 설정: ' + protectedText + '\n'
    + calibrationText
    + '명식 계산값은 상담의 흐름을 맞추기 위해 함께 흐릅니다.'
  );
}

function _sajuPromptCopyText(text) {
  var value = String(text || '');
  if (!value) return Promise.reject(new Error('empty'));
  if (navigator.clipboard && navigator.clipboard.writeText) {
    return navigator.clipboard.writeText(value);
  }
  var ta = document.createElement('textarea');
  ta.value = value;
  ta.setAttribute('readonly', 'readonly');
  ta.style.position = 'fixed';
  ta.style.left = '-9999px';
  document.body.appendChild(ta);
  ta.select();
  try {
    document.execCommand('copy');
    document.body.removeChild(ta);
    return Promise.resolve();
  } catch (err) {
    document.body.removeChild(ta);
    return Promise.reject(err);
  }
}

function _sajuPromptToast(message, tone) {
  try {
    var toast = document.createElement('div');
    toast.textContent = String(message || '');
    toast.setAttribute('role', 'status');
    toast.style.cssText = 'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:99999;max-width:min(92vw,420px);padding:10px 14px;border-radius:8px;border:1px solid rgba(230,196,112,.56);background:' + (tone === 'error' ? '#7f1d1d' : '#1f2a19') + ';color:#fff7df;font-size:.82rem;font-weight:800;box-shadow:0 18px 36px rgba(0,0,0,.28);';
    document.body.appendChild(toast);
    setTimeout(function() {
      toast.style.opacity = '0';
      toast.style.transition = 'opacity .24s ease';
      setTimeout(function() { if (toast && toast.parentNode) toast.parentNode.removeChild(toast); }, 260);
    }, 1800);
  } catch (_) {}
}

function _sajuPromptEscapeHtml(value) {
  return String(value == null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function _sajuPromptSavedResultsKey(profileId) {
  return 'codeDestiny:sajuAiConsultation:saved:' + (String(profileId || '').trim() || 'default');
}

function _sajuPromptStoreSavedResult(payload) {
  var item = payload && typeof payload === 'object' ? payload : {};
  var profileId = String(item.profileId || _sajuPromptResolveProfileId() || '').trim() || 'default';
  var resultId = String(item.resultId || item.requestId || '').trim();
  if (!resultId || !String(item.resultText || '').trim()) return false;
  var stored = {
    resultId: resultId,
    requestId: String(item.requestId || '').trim(),
    profileId: profileId,
    question: String(item.question || '').trim(),
    domain: String(item.domain || '').trim(),
    resultText: String(item.resultText || '').trim(),
    promptVersion: String(item.promptVersion || '').trim(),
    consultationType: String(item.consultationType || 'saju_myeongsik_ai').trim(),
    factSnapshot: item.factSnapshot || null,
    tenGodSnapshot: item.tenGodSnapshot || null,
    saved: true,
    savedAt: new Date().toISOString()
  };
  try {
    localStorage.setItem(_sajuPromptSavedResultsKey(profileId), JSON.stringify(stored));
    return true;
  } catch (_) {
    return false;
  }
}

function _sajuPromptReadSavedResult(profileId) {
  try {
    var raw = localStorage.getItem(_sajuPromptSavedResultsKey(profileId));
    if (!raw) return null;
    var parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object' || !String(parsed.resultText || '').trim()) return null;
    return parsed;
  } catch (_) {
    return null;
  }
}

function _sajuPromptChapterTitle(line) {
  var text = String(line || '').trim().replace(/^#+\s*/, '').replace(/^\d{1,2}[.)]\s*/, '');
  var titles = [
    '질문에 대한 핵심 답변',
    '이 명식의 중심 성향',
    '십성 구조 해석',
    '오행 균형 해석',
    '현재 고민과 명식의 연결',
    '일/돈/관계/연애/건강 리듬',
    '대운의 전환점',
    '올해의 흐름',
    '조심해야 할 패턴',
    '살리는 전략',
    '30일 실천 가이드',
    '마지막 한마디'
  ];
  for (var i = 0; i < titles.length; i += 1) {
    if (text.indexOf(titles[i]) === 0) return titles[i];
  }
  return '';
}

function _sajuPromptRenderChapters(text) {
  var lines = String(text || '').split(/\n+/);
  var html = '';
  var open = false;
  function ensureOpen(title) {
    if (open) html += '</section>';
    html += '<section style="padding:15px 14px;border-top:1px solid rgba(113,63,18,.12);"><h4 style="margin:0 0 9px;color:#4a2e11;font-size:.96rem;line-height:1.42;font-weight:950;">' + _sajuPromptEscapeHtml(title || '상담 흐름') + '</h4>';
    open = true;
  }
  lines.forEach(function(line) {
    var trimmed = String(line || '').trim();
    if (!trimmed) return;
    var title = _sajuPromptChapterTitle(trimmed);
    if (title) {
      ensureOpen(title);
      return;
    }
    if (!open) ensureOpen('핵심 상담');
    html += '<p style="margin:0 0 10px;color:#1f2a19;font-size:.88rem;line-height:1.86;word-break:keep-all;">' + _sajuPromptEscapeHtml(trimmed) + '</p>';
  });
  if (open) html += '</section>';
  return html || '<section style="padding:14px;"><p style="margin:0;color:#1f2a19;">상담문을 불러오지 못했습니다.</p></section>';
}

// 기본 코스믹 상담(자미두수·점성술·베다·숙요) 공용 답변 렌더.
// 어두운 코스믹 패널용 밝은 텍스트를 쓰고, 잘린 JSON 원문이 새어도 중괄호를
// 노출하지 않도록 방어한다(문자열 값만 추출/치환). window에도 노출해 숙요 엔진에서 재사용한다.
function _cdRenderConsultAnswerHtml(text) {
  var raw = String(text || '').replace(/\r\n/g, '\n').trim();
  raw = raw.replace(/```[a-zA-Z]*\n?/g, '').replace(/```/g, '').trim();
  // JSON 방어: 프로즈 라우트지만 완전/잘린 JSON이 새어도 사람 문장만 남긴다(중괄호 노출 금지).
  if (/^[\[{]/.test(raw)) {
    var extracted = '';
    try {
      var parsed = JSON.parse(raw);
      var collected = [];
      (function walk(v) {
        if (typeof v === 'string') { if (v.trim()) collected.push(v.trim()); }
        else if (Array.isArray(v)) { v.forEach(walk); }
        else if (v && typeof v === 'object') { Object.keys(v).forEach(function(k) { walk(v[k]); }); }
      })(parsed);
      extracted = collected.join('\n\n');
    } catch (_) {
      extracted = raw.replace(/"[a-zA-Z_][\w]*"\s*:/g, ' ').replace(/[{}\[\]"]/g, ' ').replace(/[ \t]+/g, ' ').replace(/\s*,\s*/g, '\n').trim();
    }
    if (extracted) raw = extracted;
  }
  if (!raw) return '<p style="margin:0;color:#e9d5ff;">상담문을 불러오지 못했습니다. 다시 시도해 주세요.</p>';
  var lines = raw.split(/\n+/);
  var html = '';
  lines.forEach(function(line) {
    var t = String(line || '').trim();
    if (!t) return;
    t = t.replace(/^#{1,4}\s*/, '');
    var headMatch = t.match(/^(\d{1,2})\s*[.)]\s*(.+)$/);
    var boldMatch = t.match(/^\*\*(.+?)\*\*\s*[:：]?\s*$/);
    if (headMatch && headMatch[2].length <= 40) {
      html += '<h4 style="margin:17px 0 8px;color:#fde68a;font-size:0.95rem;font-weight:900;line-height:1.5;word-break:keep-all;">'
        + _sajuPromptEscapeHtml(headMatch[1] + '. ' + headMatch[2].replace(/\*\*/g, '')) + '</h4>';
    } else if (boldMatch) {
      html += '<h4 style="margin:17px 0 8px;color:#fde68a;font-size:0.95rem;font-weight:900;line-height:1.5;word-break:keep-all;">'
        + _sajuPromptEscapeHtml(boldMatch[1]) + '</h4>';
    } else {
      html += '<p style="margin:0 0 11px;color:#ede9fe;font-size:0.86rem;line-height:1.86;word-break:keep-all;">'
        + _sajuPromptEscapeHtml(t).replace(/\*\*(.+?)\*\*/g, '<strong style="color:#ffffff;">$1</strong>') + '</p>';
    }
  });
  return html || '<p style="margin:0;color:#e9d5ff;">상담문을 불러오지 못했습니다.</p>';
}
try { if (typeof window !== 'undefined') window._cdRenderConsultAnswerHtml = _cdRenderConsultAnswerHtml; } catch (_) {}

// 유료 상담 생성 POST의 일시 인프라 503/네트워크 오류를 동일 requestId로 자동 재시도(멱등 소비라 이중차감 없음).
// 확정 응답(200/402/401/400)은 즉시 반환. LLM 생성 실패는 서버가 500으로 내려 여기서 재시도되지 않는다.
function _cdIsTransientConsultResult(result) {
  if (!result) return true;
  if (Number(result.status || 0) === 503) return true;
  var code = String((result.payload && result.payload.code) || '').toUpperCase();
  return code === 'SERVICE_TEMPORARILY_UNAVAILABLE'
    || code === 'PAID_ACCESS_VERIFY_RETRYABLE'
    || code === 'DB_DEGRADED'
    || code === 'BALANCE_SNAPSHOT_UNAVAILABLE'
    || code === 'AUTH_STATUS_TEMPORARILY_UNAVAILABLE';
}
function _cdRetryTransientPost(fetchFn, opts) {
  var o = opts || {};
  var maxAttempts = Math.max(1, o.maxAttempts || 3);
  var baseDelayMs = o.baseDelayMs || 900;
  function attempt(n) {
    return Promise.resolve().then(fetchFn).then(function(result) {
      if (n < maxAttempts && _cdIsTransientConsultResult(result)) {
        return new Promise(function(resolve) { setTimeout(resolve, baseDelayMs * n); })
          .then(function() { return attempt(n + 1); });
      }
      return result;
    }).catch(function(err) {
      // 네트워크 예외(fetch reject)도 전이로 간주해 백오프 재시도.
      if (n < maxAttempts) {
        return new Promise(function(resolve) { setTimeout(resolve, baseDelayMs * n); })
          .then(function() { return attempt(n + 1); });
      }
      throw err;
    });
  }
  return attempt(1);
}
try {
  if (typeof window !== 'undefined') {
    window._cdRetryTransientPost = _cdRetryTransientPost;
    window._cdIsTransientConsultResult = _cdIsTransientConsultResult;
  }
} catch (_) {}

function _sajuPromptBuildResultSummaryHtml(payload) {
  var item = payload && typeof payload === 'object' ? payload : {};
  var text = String(item.resultText || '').replace(/\s+/g, ' ').trim();
  var summary = text.length > 260 ? text.slice(0, 260) + '…' : text;
  return '<div style="margin:13px 13px 0;border:1px solid rgba(180,121,38,.22);background:linear-gradient(135deg,rgba(255,247,223,.9),rgba(255,255,255,.72));border-radius:8px;padding:12px;">'
    + '<div style="font-size:.72rem;color:#8a5a16;font-weight:950;letter-spacing:.08em;">핵심 요약</div>'
    + '<p style="margin:6px 0 0;color:#2a2117;font-size:.86rem;line-height:1.72;word-break:keep-all;">' + _sajuPromptEscapeHtml(summary) + '</p>'
    + '</div>';
}

// 계산 근거(analysis basis)를 그룹 카드로 그린다. 용어 풀이는 title 속성으로 붙여
// 마우스와 스크린리더 양쪽에서 읽히게 한다(React 쪽 GlossaryTerm과 같은 문장을 서버가 내려 준다).
function _sajuPromptRenderBasisGroups(basis, options) {
  var groups = basis && Array.isArray(basis.groups) ? basis.groups : [];
  if (!groups.length) return '';
  var opts = options && typeof options === 'object' ? options : {};
  var dark = opts.dark === true;
  var text = dark ? '#fff7df' : '#3b2a14';
  var muted = dark ? 'rgba(255,247,223,.7)' : '#7c5a20';
  var line = dark ? 'rgba(255,247,223,.18)' : 'rgba(113,63,18,.16)';
  var surface = dark ? 'rgba(255,247,223,.06)' : 'rgba(255,252,243,.72)';
  return groups.map(function(group) {
    var items = Array.isArray(group.items) ? group.items : [];
    if (!items.length) return '';
    var rows = items.map(function(item) {
      var hint = String(item.termHint || '').trim();
      var label = '<span style="font-weight:900;font-size:.72rem;color:' + muted + ';'
        + (hint ? 'text-decoration:underline dotted;text-underline-offset:3px;cursor:help;' : '')
        + '"' + (hint ? ' title="' + _sajuPromptEscapeHtml(hint) + '"' : '') + '>' + _sajuPromptEscapeHtml(item.label) + '</span>';
      var accent = item.tone === 'caution' || item.tone === 'positive'
        ? 'box-shadow:inset 2px 0 0 0 ' + (dark ? 'rgba(253,230,138,.55)' : 'rgba(113,63,18,.4)') + ';'
        : '';
      return '<div style="display:grid;grid-template-columns:minmax(72px,auto) minmax(0,1fr);gap:3px 10px;align-items:baseline;'
        + 'border-radius:8px;padding:5px 7px;background:' + surface + ';' + accent + '">'
        + label
        + '<span style="font-size:.78rem;font-weight:600;line-height:1.6;color:' + text + ';word-break:break-word;">' + _sajuPromptEscapeHtml(item.value) + '</span>'
        + '</div>';
    }).join('');
    return '<div style="border:1px solid ' + line + ';border-radius:8px;padding:11px;margin-top:8px;">'
      + '<div style="font-size:.74rem;font-weight:900;letter-spacing:.03em;color:' + text + ';">' + _sajuPromptEscapeHtml(group.title) + '</div>'
      + (group.hint ? '<div style="margin-top:3px;font-size:.68rem;line-height:1.55;color:' + muted + ';">' + _sajuPromptEscapeHtml(group.hint) + '</div>' : '')
      + '<div style="display:grid;gap:5px;margin-top:8px;">' + rows + '</div>'
      + '</div>';
  }).join('');
}

function _sajuPromptBuildBasisHtml(payload) {
  // 근거가 함께 저장된 결과는 전체 확정값을 펼쳐 보여 준다(이 변경 이전 결과는 아래 요약 칩으로 폴백).
  var basisGroupsHtml = _sajuPromptRenderBasisGroups(payload && payload.analysisBasis);
  if (basisGroupsHtml) {
    return '<div style="margin:10px 13px 0;border:1px solid rgba(113,63,18,.14);background:rgba(255,252,243,.72);border-radius:8px;padding:11px;">'
      + '<div style="font-size:.8rem;font-weight:900;color:#2a2117;">이 상담이 계산한 값</div>'
      + '<div style="margin-top:3px;font-size:.7rem;color:#7c5a20;line-height:1.55;">AI가 지어낸 값이 아니라, 입력하신 명식으로 계산된 결과입니다.</div>'
      + basisGroupsHtml
      + '</div>';
  }
  var fact = payload && payload.factSnapshot && typeof payload.factSnapshot === 'object' ? payload.factSnapshot : {};
  var day = fact.dayMaster || {};
  var ten = fact.heavenlyStemTenGods || {};
  var chips = [];
  if (day.stem) chips.push('기준 일간 ' + day.stem + (day.elementKo ? ' · ' + day.elementKo : '') + (day.yinYangKo ? ' · ' + day.yinYangKo : ''));
  ['year', 'month', 'day', 'hour'].forEach(function(key) {
    var row = ten[key] || {};
    if (row.stem && row.tenGod) chips.push(row.label + ' ' + row.stem + ' ' + row.tenGod);
  });
  var trust = '<div style="font-size:.72rem;color:#7c5a20;line-height:1.55;margin-top:7px;">내부 명식 기준으로 해석되었습니다. 십성은 서버 계산값을 기준으로 고정했습니다.</div>';
  return '<div style="margin:10px 13px 0;border:1px solid rgba(113,63,18,.14);background:rgba(255,252,243,.72);border-radius:8px;padding:11px;">'
    + '<div style="display:flex;gap:6px;flex-wrap:wrap;">'
    + (chips.length ? chips.map(function(chip) { return '<span style="border:1px solid rgba(113,63,18,.18);background:#fff7df;color:#4a2e11;border-radius:999px;padding:6px 8px;font-size:.72rem;font-weight:900;">' + _sajuPromptEscapeHtml(chip) + '</span>'; }).join('') : '<span style="color:#6b4e16;font-size:.76rem;">명식 기준 정보가 함께 저장되었습니다.</span>')
    + '</div>' + trust + '</div>';
}

function _sajuPromptBuildQuestionHtml(payload) {
  var question = String(payload && payload.question || '').trim();
  if (!question) return '';
  return '<div style="margin:10px 13px 0;padding:10px 11px;border-left:3px solid #c89236;background:rgba(120,53,15,.06);border-radius:8px;color:#3b2a14;font-size:.82rem;line-height:1.65;word-break:keep-all;"><b>질문</b><br>' + _sajuPromptEscapeHtml(question) + '</div>';
}

function _sajuPromptBuildShareText(payload) {
  var item = payload && typeof payload === 'object' ? payload : {};
  var fact = item.factSnapshot && typeof item.factSnapshot === 'object' ? item.factSnapshot : {};
  var day = fact.dayMaster || {};
  var question = String(item.question || '').trim();
  var body = String(item.resultText || '').replace(/\s+/g, ' ').trim();
  if (body.length > 900) body = body.slice(0, 900) + '…';
  return [
    'Code Destiny 사주 AI 상담 결과',
    day.stem ? '기준 일간: ' + day.stem + (day.elementKo ? ' / ' + day.elementKo : '') + (day.yinYangKo ? ' / ' + day.yinYangKo : '') : '',
    question ? '질문: ' + question : '',
    '',
    body
  ].filter(function(line, idx) { return idx === 3 || String(line || '').trim(); }).join('\n');
}

function _sajuPromptApiUrls(path) {
  var urls = [path];
  try {
    var base = typeof getFortuneApiBaseUrl === 'function' ? getFortuneApiBaseUrl() : '';
    if (base) {
      var full = String(base).replace(/\/+$/, '') + path;
      if (urls.indexOf(full) < 0) urls.push(full);
    }
  } catch (_) {}
  return urls;
}

function _sajuPromptShouldRetryPaidGeneration(result) {
  var payload = result && result.payload ? result.payload : {};
  var details = payload.errorDetails && typeof payload.errorDetails === 'object' ? payload.errorDetails : {};
  var code = String(payload.code || details.code || '').trim().toUpperCase();
  var reason = String(details.reason || payload.reason || '').trim().toUpperCase();
  var message = String(payload.message || details.message || '').trim();
  var status = Number(result && result.status);
  // 🔴 환불이 끝난 실패는 재시도 대상이 아니다. 서버는 환불된 차감을 결제 증빙으로 인정하지 않으므로
  // 같은 증빙으로 재-POST 하면 무조건 402 가 오고, 사용자에게는 "결제했는데 또 결제창"으로 보인다.
  if (payload.refundOk === true || details.refundOk === true) return false;
  // 524 는 Cloudflare 가 동기 생성 도중 연결을 끊은 것이다. 재-POST 는 서버의 재연결 분기를 타
  // (완료면 저장분, 진행 중이면 202) 재차감 없이 폴링으로 전환된다.
  return status === 503
    || status === 502
    || status === 504
    || status === 524
    || code === 'SERVICE_UNAVAILABLE'
    || code === 'PAID_ACCESS_VERIFY_RETRYABLE'
    || code === 'LLM_GENERATION_RETRYABLE'
    || reason === 'DB_UNAVAILABLE'
    || /database is temporarily unavailable/i.test(message);
}

function _sajuPromptPendingStorageKey(profileId) {
  return 'codeDestiny:sajuAiConsultation:pending:' + (String(profileId || '').trim() || 'default');
}

function _sajuPromptStorePendingJob(job) {
  try {
    var profileId = String((job && job.profileId) || '').trim();
    localStorage.setItem(_sajuPromptPendingStorageKey(profileId), JSON.stringify(Object.assign({}, job, {
      savedAt: Date.now()
    })));
  } catch (_) {}
}

function _sajuPromptReadPendingJob(profileId) {
  try {
    var raw = localStorage.getItem(_sajuPromptPendingStorageKey(profileId));
    if (!raw) return null;
    var job = JSON.parse(raw);
    if (!job || typeof job !== 'object') return null;
    if (Date.now() - Number(job.savedAt || 0) > 24 * 60 * 60 * 1000) {
      localStorage.removeItem(_sajuPromptPendingStorageKey(profileId));
      return null;
    }
    return job;
  } catch (_) {
    return null;
  }
}

function _sajuPromptClearPendingJob(profileId) {
  try { localStorage.removeItem(_sajuPromptPendingStorageKey(profileId)); } catch (_) {}
}

function _sajuPromptBuildQuery(params) {
  var parts = [];
  Object.keys(params || {}).forEach(function(key) {
    var value = String(params[key] || '').trim();
    if (value) parts.push(encodeURIComponent(key) + '=' + encodeURIComponent(value));
  });
  return parts.length ? '?' + parts.join('&') : '';
}

function _sajuPromptRequestGet(path) {
  var urls = _sajuPromptApiUrls(path);
  function runAt(index) {
    return _cdAIPromptRequestJson(urls[index], { method: 'GET' }).then(function(result) {
      if ((result && result.ok) || index + 1 >= urls.length) return result;
      return runAt(index + 1);
    }).catch(function(error) {
      if (index + 1 < urls.length) return runAt(index + 1);
      throw error;
    });
  }
  return runAt(0);
}

function _sajuPromptFetchStatus(job) {
  var item = job && typeof job === 'object' ? job : {};
  var jobId = String(item.jobId || item.executionId || '').trim();
  var path = '/api/fortune/saju-ai-consultation/status' + (jobId ? '/' + encodeURIComponent(jobId) : '');
  return _sajuPromptRequestGet(path + _sajuPromptBuildQuery({
    requestId: item.requestId,
    profileId: item.profileId
  }));
}

function _sajuPromptFetchResult(job) {
  var item = job && typeof job === 'object' ? job : {};
  var resultId = String(item.resultId || '').trim();
  var path = '/api/fortune/saju-ai-consultation/result' + (resultId ? '/' + encodeURIComponent(resultId) : '');
  return _sajuPromptRequestGet(path + _sajuPromptBuildQuery({
    jobId: item.jobId || item.executionId,
    requestId: item.requestId,
    profileId: item.profileId
  }));
}

function _sajuPromptPostWithPaidEvidence(requestNonce, question, privacyOptions, domain, evidence, options) {
  var urls = _sajuPromptApiUrls('/api/fortune/saju-ai-consultation/create');
  var opts = options && typeof options === 'object' ? options : {};
  var profileId = String(opts.profileId || _sajuPromptResolveProfileId() || '').trim();
  var body = {
    question: question,
    domain: String(domain || '').trim(),
    sajuResult: _buildSajuAIPromptPayload(privacyOptions),
    calibration: _sajuPromptActiveCalibration || undefined,
    requestId: evidence.requestId || ('saju-ai-prompt:' + requestNonce),
    profileId: profileId || undefined,
    selectedProfileId: profileId || undefined,
    transactionId: evidence._paymentContext && evidence._paymentContext.transactionId,
    ledgerId: evidence._paymentContext && evidence._paymentContext.ledgerId,
    purchaseId: evidence._paymentContext && evidence._paymentContext.purchaseId,
    idempotencyKey: evidence._paymentContext && evidence._paymentContext.idempotencyKey,
    accessType: evidence._paymentContext && evidence._paymentContext.accessType,
    accessMethod: evidence._paymentContext && evidence._paymentContext.accessMethod,
    paymentMode: evidence._paymentContext && evidence._paymentContext.paymentMode,
    accessGrant: evidence.accessGrant,
    accessDecision: evidence.accessDecision,
    freeBySubscription: evidence.freeBySubscription,
    consume: evidence.consume,
    payment: evidence.payment,
    _paymentContext: evidence._paymentContext
  };
  if (typeof opts.onJobRequestReady === 'function') {
    try {
      opts.onJobRequestReady({
        // 서버(readAIPromptRequestId)는 idempotencyKey 를 우선해 레코드를 키잉한다.
        // 폴링 키를 여기서 맞춰 두지 않으면 카드 경로에서 /status 가 404 로 샌다.
        requestId: String((body.idempotencyKey || body.requestId) || '').trim() || body.requestId,
        profileId: profileId,
        question: question,
        domain: String(domain || '').trim(),
        privacyOptions: privacyOptions,
        paidEvidence: evidence
      });
    } catch (_) {}
  }
  function runAt(index, attempt) {
    return _cdAIPromptRequestJson(urls[index], {
      method: 'POST',
      headers: { 'idempotency-key': evidence.requestId || ('saju-ai:' + requestNonce) },
      body: JSON.stringify(body)
    }).then(function(result) {
      if (result && result.ok) return result;
      if (_sajuPromptShouldRetryPaidGeneration(result) && attempt < 1) {
        if (typeof opts.onRetry === 'function') {
          try { opts.onRetry(result); } catch (_) {}
        }
        return new Promise(function(resolve) {
          setTimeout(resolve, 750);
        }).then(function() {
          return runAt(index, attempt + 1);
        });
      }
      if (index + 1 < urls.length) return runAt(index + 1, attempt);
      return result;
    }).catch(function(error) {
      if (index + 1 < urls.length) return runAt(index + 1, attempt);
      if (attempt < 1) {
        if (typeof opts.onRetry === 'function') {
          try { opts.onRetry(null); } catch (_) {}
        }
        return new Promise(function(resolve) {
          setTimeout(resolve, 750);
        }).then(function() {
          return runAt(index, attempt + 1);
        });
      }
      throw error;
    });
  }
  return runAt(0, 0);
}

function _sajuPromptResolveProfileId() {
  try {
    if (typeof window._cdResolveCurrentProfileIdForAccess === 'function') {
      var resolved = String(window._cdResolveCurrentProfileIdForAccess() || '').trim();
      if (resolved) return resolved;
    }
  } catch (_) {}
  try {
    var currentProfile = window.__cdCurrentDestinyProfile
      || window.__cdCurrentProfile
      || window.currentDestinyProfile
      || window.selectedDestinyProfile
      || null;
    if (!currentProfile && window.DestinyProfileManager && window.DestinyProfileManager.storage && typeof window.DestinyProfileManager.storage.current === 'function') {
      currentProfile = window.DestinyProfileManager.storage.current();
    }
    var currentId = String((currentProfile && (currentProfile.profileId || currentProfile.id)) || '').trim();
    if (currentId) return currentId.slice(0, 80).replace(/\s+/g, '_');
  } catch (_) {}
  try {
    var profile = window.__cdActiveBirthProfile || window.__destinyFlowerSajuSnapshot || null;
    var profileId = String((profile && (profile.profileId || profile.id)) || '').trim();
    if (profileId) return profileId.slice(0, 80).replace(/\s+/g, '_');
  } catch (_) {}
  try {
    if (typeof window._cdGetCurrentProfileFromStorage === 'function') {
      var stored = window._cdGetCurrentProfileFromStorage();
      var storedId = String((stored && (stored.profileId || stored.id)) || '').trim();
      if (storedId) return storedId.slice(0, 80).replace(/\s+/g, '_');
    }
  } catch (_) {}
  try {
    var directId = String(window.__cdCurrentProfileId || window.currentProfileId || window.selectedProfileId || '').trim();
    if (directId) return directId.slice(0, 80).replace(/\s+/g, '_');
  } catch (_) {}
  return '';
}

function _requestSajuQuestionPrompt(question, privacyOptions, domain, options) {
  var opts = options && typeof options === 'object' ? options : {};
  var requestNonce = _sajuPromptBuildCurrentRequestNonce(domain, question);
  var savedEvidence = opts.paidEvidence && typeof opts.paidEvidence === 'object' ? opts.paidEvidence : null;
  function attachEvidence(result) {
    if (result && typeof result === 'object' && savedEvidence) result._sajuPaidEvidence = savedEvidence;
    return result;
  }
  if (savedEvidence) {
    return _sajuPromptPostWithPaidEvidence(requestNonce, question, privacyOptions, domain, savedEvidence, options).then(attachEvidence);
  }
  return _cdAIPromptGate({
    featureKey: 'saju_ai_prompt_generator',
    reason: '사주 AI 상담 결과 생성',
    cost: 200,
    amountKrw: 20000,
    paymentAmount: 20000,
    requestId: 'saju-ai-prompt:' + requestNonce,
    categoryKey: 'saju'
  }).then(function(gateResult) {
    if (!gateResult.ok) return _cdAIPromptFailureResult(gateResult);
    savedEvidence = _cdAIPromptGateEvidence(gateResult);
    if (typeof opts.onPaidEvidence === 'function') {
      try { opts.onPaidEvidence(savedEvidence); } catch (_) {}
    }
    return _sajuPromptPostWithPaidEvidence(requestNonce, question, privacyOptions, domain, savedEvidence, options);
  }).then(attachEvidence);
}

