    document.getElementById('astroResult').innerHTML = html;

    function _astroInitBirthMapSection(){
      var wrap = document.getElementById('astroBirthMapSection');
      if(!wrap || wrap.getAttribute('data-init') === '1') return;
      wrap.setAttribute('data-init', '1');

      var modeBtn = document.getElementById('astroBirthModeToggle');
      var readingModeBtn = document.getElementById('astroReadingModeToggle');
      var bodyWrap = document.getElementById('astroBodyWrap');
      function applyMode(detailMode){
        if(bodyWrap){
          bodyWrap.classList.toggle('is-detail', !!detailMode);
          bodyWrap.classList.toggle('is-easy', !detailMode);
        }
        if(detailMode){
          wrap.classList.remove('is-beginner');
        } else {
          wrap.classList.add('is-beginner');
        }
        if(modeBtn){
          modeBtn.setAttribute('aria-pressed', detailMode ? 'true' : 'false');
          modeBtn.textContent = detailMode ? '전체 리딩 ON' : '핵심 요약 ON';
        }
        if(readingModeBtn){
          readingModeBtn.setAttribute('aria-pressed', detailMode ? 'true' : 'false');
          readingModeBtn.textContent = detailMode ? '핵심만 보기로 줄이기' : '전체 리딩 다시 펼치기';
        }
      }
      applyMode(false);

      if(modeBtn){
        modeBtn.addEventListener('click', function(){
          var nextMode = modeBtn.getAttribute('aria-pressed') !== 'true';
          applyMode(nextMode);
        });
      }
      if(readingModeBtn && readingModeBtn.getAttribute('data-bound') !== '1'){
        readingModeBtn.setAttribute('data-bound', '1');
        readingModeBtn.addEventListener('click', function(){
          var nextMode = readingModeBtn.getAttribute('aria-pressed') !== 'true';
          applyMode(nextMode);
        });
      }
      Array.prototype.forEach.call(document.querySelectorAll('[data-astro-open-target]'), function(actionBtn){
        if(!actionBtn || actionBtn.getAttribute('data-bound') === '1') return;
        actionBtn.setAttribute('data-bound', '1');
        actionBtn.addEventListener('click', function(){
          var targetId = actionBtn.getAttribute('data-astro-open-target');
          var target = targetId ? document.getElementById(targetId) : null;
          if(!target) return;
          var detailLayer = document.getElementById('astroDetailLayer');
          if(detailLayer && detailLayer.contains(target)) applyMode(true);
          window.setTimeout(function(){
            var scrollTarget = target.closest && target.closest('.astro-section') ? target.closest('.astro-section') : target;
            var scrollHost = scrollTarget ? scrollTarget.parentElement : null;
            while(scrollHost && scrollHost !== document.body){
              var hostStyle = window.getComputedStyle ? window.getComputedStyle(scrollHost) : null;
              var canScroll = scrollHost.scrollHeight > scrollHost.clientHeight + 4;
              var overflowY = hostStyle ? String(hostStyle.overflowY || hostStyle.overflow || '') : '';
              if(canScroll && /auto|scroll/i.test(overflowY)) break;
              scrollHost = scrollHost.parentElement;
            }
            if(scrollTarget && scrollHost && scrollHost !== document.body){
              var hostRect = scrollHost.getBoundingClientRect();
              var targetRect = scrollTarget.getBoundingClientRect();
              var nextTop = Math.max(0, scrollHost.scrollTop + targetRect.top - hostRect.top - 14);
              scrollHost.scrollTop = nextTop;
            } else if(scrollTarget && typeof scrollTarget.scrollIntoView === 'function'){
              scrollTarget.scrollIntoView({ behavior:'smooth', block:'start' });
            }
            if(typeof target.focus === 'function'){
              try { target.focus({ preventScroll:true }); } catch(_) { target.focus(); }
            }
          }, 80);
        });
      });

      function bindTouchGuard(summaryEl){
        if(!summaryEl || summaryEl.getAttribute('data-touch-guard') === '1') return;
        summaryEl.setAttribute('data-touch-guard', '1');
        var touchState = null;
        summaryEl.addEventListener('touchstart', function(ev){
          var t = ev.touches && ev.touches[0];
          if(!t) return;
          touchState = { x:t.clientX, y:t.clientY, moved:false };
        }, { passive:true });
        summaryEl.addEventListener('touchmove', function(ev){
          if(!touchState) return;
          var t = ev.touches && ev.touches[0];
          if(!t) return;
          if(Math.abs(t.clientX - touchState.x) > 10 || Math.abs(t.clientY - touchState.y) > 10){
            touchState.moved = true;
          }
        }, { passive:true });
        summaryEl.addEventListener('touchcancel', function(){ touchState = null; }, { passive:true });
        summaryEl.addEventListener('click', function(ev){
          if(touchState && touchState.moved){
            ev.preventDefault();
            ev.stopPropagation();
          }
          touchState = null;
        }, true);
      }

      var detailsEls = document.querySelectorAll('#astroBirthMapSection details.astro-birth-card, #astroBirthMapSection details.astro-birth-help, #astroAspectStorySection details.astro-birth-aspect, #astroLifeAreaSection details.astro-life-card');
      detailsEls.forEach(function(el){
        var summary = el.querySelector('summary');
        if(summary){
          summary.setAttribute('aria-expanded', el.open ? 'true' : 'false');
          bindTouchGuard(summary);
        }
        el.addEventListener('toggle', function(){
          var curSummary = el.querySelector('summary');
          if(curSummary){
            curSummary.setAttribute('aria-expanded', el.open ? 'true' : 'false');
          }
        });
      });
    }
    _astroInitBirthMapSection();

    function _astroPromptClone(value) {
      try {
        return JSON.parse(JSON.stringify(value));
      } catch (_) {
        return null;
      }
    }

    function _astroHouseLabel(value) {
      var n = Number(value);
      if (!Number.isFinite(n) || n <= 0) return '-';
      return String(Math.trunc(n)) + 'H';
    }

    function _astroQuestionTypeLabel(type) {
      var map = {
        compatibility: '궁합/시나스트리',
        love: '연애/관계',
        career: '직업/커리어',
        money: '돈/재정',
        health: '건강/멘탈',
        life_direction: '인생 방향',
        relationship: '인간관계',
        general: '일반'
      };
      return map[String(type || 'general')] || map.general;
    }

    function _astroBuildPromptContext() {
      var placements = Array.isArray(placementData) ? placementData.slice(0, 12).map(function(row) {
        return {
          planet: String(row && row.planet || ''),
          sign: String(row && row.sign || ''),
          house: row && row.wholeSignHouse ? (String(row.wholeSignHouse) + 'H') : '-',
          degree: (row && Number.isFinite(Number(row.lon))) ? (Number(row.lon).toFixed(2) + '°') : '-'
        };
      }) : [];

      var majorAspects = Array.isArray(majorAspectRows) ? majorAspectRows.slice(0, 12).map(function(row) {
        var text = String(row && row.text || '').trim();
        return {
          pair: text || '주요 각도',
          aspect: String(row && row.aspectName || row && row.aspect || '').trim() || '-',
          orb: Number.isFinite(Number(row && row.orb)) ? (Number(row.orb).toFixed(2) + '°') : '-'
        };
      }) : [];

      var astrologyResult = {
        birth: {
          year: y,
          month: m,
          day: d,
          hour: h,
          minute: min,
          timezone: 'UTC' + (tz >= 0 ? '+' : '') + tz,
          latitude: lat,
          longitude: lon
        },
        coreSigns: {
          sun: sunSign,
          moon: moonSign,
          asc: ascSign,
          mc: mcSign,
          desc: descSign
        },
        elements: {
          dominant: elemDominant,
          weakest: elemWeakest,
          counts: {
            fire: elemCount.fire,
            earth: elemCount.earth,
            air: elemCount.air,
            water: elemCount.water
          },
          percentages: {
            fire: elemPct.fire,
            earth: elemPct.earth,
            air: elemPct.air,
            water: elemPct.water
          }
        },
        modalities: {
          dominant: modalityDominant,
          counts: {
            cardinal: modalityCount.cardinal,
            fixed: modalityCount.fixed,
            mutable: modalityCount.mutable
          },
          advice: modalityAdvice[modalityDominant] || ''
        },
        focus: {
          topHouse: topFocusHouse ? String(topFocusHouse) + 'H' : '-',
          topHouseTopic: topHouseTopic,
          focusCount: topFocusCount
        },
        transits: {
          jupiterTransit: jupiterTransit,
          jupiterIndex: jupiterIndex,
          message: transitMsg[jupiterIndex] || ''
        },
        timelord: {
          firdaria: {
            main: firdariaMain ? firdariaMain.kr : '',
            sub: firdariaSubPlanet,
            yearsLeft: firdariaMainYearsLeft
          },
          profection: {
            house: profHouse,
            sign: profSign,
            ruler: profRuler,
            theme: (profectionDynamic && profectionDynamic.theme) || (curProfData && curProfData.theme) || ''
          }
        },
        placements: placements,
        majorAspects: majorAspects
      };

      return {
        astrologyResult: astrologyResult,
        compatibilityResult: _astroPromptClone(astroLatestCompatibilityResult)
      };
    }

    function _astroPromptEscapeHtml(value) {
      return String(value == null ? '' : value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
    }

