  function _zwNormalizeLifeAnimalStar(raw) {
    var cleaned = _zwPortfolioCleanStar(raw).replace(/\s+/g, '');
    if (!cleaned) return '';
    if (ZW_LIFE_ANIMAL_ALIAS_TO_HAN[cleaned]) return ZW_LIFE_ANIMAL_ALIAS_TO_HAN[cleaned];
    var noSuffix = cleaned.replace(/성$/, '');
    if (ZW_LIFE_ANIMAL_ALIAS_TO_HAN[noSuffix]) return ZW_LIFE_ANIMAL_ALIAS_TO_HAN[noSuffix];
    return '';
  }

  function _zwFindPalaceRowByName(pd, palaceName) {
    if (!pd || !Array.isArray(pd.palaceStarData)) return null;
    for (var i = 0; i < pd.palaceStarData.length; i += 1) {
      var row = pd.palaceStarData[i];
      if (row && row.palace === palaceName) return row;
    }
    return null;
  }

  function _zwFindMingRow(pd) {
    var row = _zwFindPalaceRowByName(pd, '명궁');
    if (row) return row;
    if (!pd || !Array.isArray(pd.palaceStarData) || !Array.isArray(pd.palacesByIndex)) return null;
    var idx = pd.palacesByIndex.indexOf('명궁');
    return idx >= 0 ? pd.palaceStarData[idx] : null;
  }

  function _zwLifeAnimalStrengthScore(starName, branch, isBorrowed) {
    var scoreMap = { '묘': 5, '왕': 4, '평': 3, '리': 2, '함': 1 };
    var br = zwComputeStarStrength(starName, branch || '', !!isBorrowed) || '평';
    var norm = zwNormalizeStrength(br);
    return scoreMap[norm] || 3;
  }

  function _zwExtractLifeMainEntries(row) {
    if (!row || !Array.isArray(row.stars)) return [];
    var entries = [];
    row.stars.forEach(function(raw, idx) {
      var parsed = _zwParseMainRaw(raw);
      if (!parsed || !parsed.name) return;
      var han = _zwNormalizeLifeAnimalStar(parsed.name);
      if (!han || !ZW_LIFE_ANIMAL_MAP[han]) return;
      entries.push({
        han: han,
        name: parsed.name,
        borrowed: !!parsed.borrowed,
        fromAux: false,
        index: idx,
        branch: row.branch || ''
      });
    });
    return entries;
  }

  function _zwExtractLifeAuxEntries(row) {
    if (!row || !Array.isArray(row.auxStars)) return [];
    var entries = [];
    row.auxStars.forEach(function(raw, idx) {
      var name = _zwPortfolioCleanStar(raw);
      if (!name) return;
      var han = _zwNormalizeLifeAnimalStar(name);
      if (!han || !ZW_LIFE_ANIMAL_MAP[han]) return;
      entries.push({
        han: han,
        name: name,
        borrowed: false,
        fromAux: true,
        index: idx,
        branch: row.branch || ''
      });
    });
    return entries;
  }

  function _zwDedupLifeEntries(entries) {
    var seen = {};
    var out = [];
    (entries || []).forEach(function(entry) {
      if (!entry || !entry.han || seen[entry.han]) return;
      seen[entry.han] = true;
      out.push(entry);
    });
    return out;
  }

  function _zwBuildLifeAnimalCombo(primaryKey, secondaryKey) {
    if (!primaryKey || !secondaryKey) return '';
    var direct = ZW_LIFE_ANIMAL_COMBO_TEXT[primaryKey + '|' + secondaryKey];
    if (direct) return direct;
    var reverse = ZW_LIFE_ANIMAL_COMBO_TEXT[secondaryKey + '|' + primaryKey];
    if (reverse) return reverse;
    var p = ZW_LIFE_ANIMAL_MAP[primaryKey];
    var s = ZW_LIFE_ANIMAL_MAP[secondaryKey];
    if (!p || !s) return '';
    return p.archetype + ' ' + p.animal + '의 ' + (p.keywords[0] || '핵심성')
      + '과 ' + s.archetype + ' ' + s.animal + '의 ' + (s.keywords[0] || '보조성')
      + '이 결합되어, 상황 판단의 깊이와 실행 방식의 폭이 함께 커지는 타입입니다.';
  }

  function _zwResolveLifeAnimal(pd) {
    var mingRow = _zwFindMingRow(pd);
    var directEntries = _zwDedupLifeEntries(_zwExtractLifeMainEntries(mingRow));
    var sourceMode = 'ming';
    var sourcePalaces = ['명궁'];
    var fallbackNote = '';

    if (!directEntries.length) {
      var fallbackRows = ['재백궁', '관록궁', '천이궁'];
      var ranked = [];

      fallbackRows.forEach(function(name, palaceOrder) {
        var row = _zwFindPalaceRowByName(pd, name);
        if (!row) return;
        sourcePalaces.push(name);

        var candidates = _zwDedupLifeEntries(_zwExtractLifeMainEntries(row));
        if (!candidates.length) {
          candidates = _zwDedupLifeEntries(_zwExtractLifeAuxEntries(row));
        }

        candidates.forEach(function(entry, starOrder) {
          var strength = _zwLifeAnimalStrengthScore(entry.name, entry.branch, entry.borrowed);
          var weighted = strength * 10
            + (entry.fromAux ? -2 : 0)
            + (3 - palaceOrder)
            - (starOrder * 0.1);
          ranked.push({
            han: entry.han,
            name: entry.name,
            fromAux: !!entry.fromAux,
            score: weighted,
            palace: name
          });
        });
      });

      ranked.sort(function(a, b) {
        return b.score - a.score;
      });

      if (ranked.length) {
        var picked = [];
        var seen = {};
        ranked.forEach(function(item) {
          if (picked.length >= 2) return;
          if (seen[item.han]) return;
          seen[item.han] = true;
          picked.push({
            han: item.han,
            name: item.name,
            borrowed: false,
            fromAux: !!item.fromAux,
            index: picked.length,
            branch: '',
            viaPalace: item.palace
          });
        });
        directEntries = picked;
        sourceMode = 'sanbang';
        fallbackNote = '명궁에 직접 들어온 주성이 약하거나 비어 있어, 삼방사정에서 들어오는 별의 기운을 통해 상징 동물을 보조 판정했습니다.';
      } else {
        sourceMode = 'hidden';
      }
    }

    var primaryKey = directEntries[0] ? directEntries[0].han : '';
    var secondaryKey = directEntries[1] ? directEntries[1].han : '';
    var primary = primaryKey ? ZW_LIFE_ANIMAL_MAP[primaryKey] : null;
    var secondary = secondaryKey ? ZW_LIFE_ANIMAL_MAP[secondaryKey] : null;

    return {
      sourceMode: sourceMode,
      sourcePalaces: sourcePalaces.filter(function(v, idx, arr){ return arr.indexOf(v) === idx; }),
      fallbackNote: fallbackNote,
      primaryKey: primaryKey,
      secondaryKey: secondaryKey,
      primary: primary,
      secondary: secondary,
      comboText: _zwBuildLifeAnimalCombo(primaryKey, secondaryKey),
      mainStars: directEntries.map(function(entry) { return entry.han; }),
      lifePalace: mingRow || null
    };
  }

  function _zwBuildLifeAnimalInsight(primary, secondary, resolved) {
    function _zwHasBatchim(word) {
      var text = String(word || '').trim();
      if (!text) return false;
      var lastChar = text.charCodeAt(text.length - 1);
      if (lastChar < 0xac00 || lastChar > 0xd7a3) return false;
      return ((lastChar - 0xac00) % 28) !== 0;
    }

    function _zwSubjectParticle(word) {
      return _zwHasBatchim(word) ? '이' : '가';
    }

    var kw = (primary && primary.keywords) ? primary.keywords.slice(0, 5) : [];
    var kwLine = kw.length ? kw.join(', ') : '핵심 성향 데이터 없음';
    var secLine = '';
    if (secondary) {
      secLine = secondary.koreanName + '의 ' + (secondary.keywords || []).slice(0, 2).join('·') + ' 기질이 숨은 결로 작동합니다.';
    }
    var sourceBridge = (resolved && resolved.sourceMode === 'sanbang')
      ? '이번 판정은 삼방사정 흐름을 함께 반영한 보조 판정입니다. '
      : '';
    var longNarrative = '당신의 명궁 중심 주성은 ' + primary.koreanName + '이며, 상징 동물로는 ' + primary.animal + _zwSubjectParticle(primary.animal) + ' 대응됩니다. '
      + primary.summary + ' 이 기질은 단순한 성격 라벨이 아니라, 위기에서 무엇을 먼저 붙잡고 어떤 기준으로 결정을 내리는지를 보여주는 운영 원리입니다. '
      + '특히 ' + kwLine + '의 축이 강할수록 대인관계와 커리어에서 역할의 무게중심을 스스로 설정하려는 경향이 선명해집니다. '
      + sourceBridge
      + (secLine ? (secLine + ' ') : '')
      + '명궁 동물 해석은 명궁·신궁·재백궁·부부궁·관록궁·복덕궁 해석을 대체하지 않으며, 각 궁에서 드러난 데이터에 일관된 방향성을 부여하는 보조 지침으로 읽을 때 실전 활용도가 가장 높습니다.';

    return {
      keywordLine: kwLine,
      oneLine: primary.summary,
      personalityCore: primary.koreanName + '의 핵심은 ' + kw.slice(0, 3).join('·') + '입니다. 상황의 중심축을 빠르게 읽고, 자신의 기준선이 흔들리지 않도록 구조를 세우는 경향이 강합니다.',
      strengths: '강점은 ' + (primary.keywords || []).slice(0, 2).join('·') + '을 실전 행동으로 연결하는 힘입니다. 명확한 기준과 실행 타이밍을 확보하면 성과가 누적되는 패턴이 강합니다.',
      weaknesses: '약점은 강한 자기 기준이 과도할 때 유연성이 낮아질 수 있다는 점입니다. 방어적 태도가 길어지면 협업 리듬이 느려질 수 있어 피드백 창구를 의식적으로 열어두는 것이 좋습니다.',
      relationStyle: primary.animal + '형 관계 스타일은 호감보다 신뢰를 먼저 쌓는 편에 가깝습니다. 가까워질수록 책임을 크게 지는 경향이 있어, 관계의 기대치와 역할을 초기에 합의하면 갈등이 줄어듭니다.',
      workMoneyStyle: '일·재물에서는 ' + primary.archetype + ' 성향이 강하게 작동합니다. 단기 변동에 흔들리기보다 구조와 권한, 지속 가능한 수익 모델을 중시하면 장기적으로 안정적인 누적 성과를 얻기 쉽습니다.',
      todayTip: '오늘의 활용법은 중요한 선택에서 감정의 즉흥 반응보다 기준 문장 1개를 먼저 세우는 것입니다. 기준이 선명할수록 판단 피로가 줄고 결과의 일관성이 높아집니다.',
      caution: '주의할 점은 과도한 단독 판단입니다. 검증 파트너 1명을 지정해 관점 교차를 습관화하면 강점은 유지하면서 리스크를 크게 줄일 수 있습니다.',
      tamagotchiLine: '네 안의 ' + primary.animal + '이 길을 안내합니다. 기준을 잃지 않되, 따뜻한 한 문장으로 사람을 먼저 안심시키는 태도가 좋습니다.',
      longNarrative: longNarrative
    };
  }

  function _zwBuildLifeAnimalCodex(primaryKey) {
    return '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px">'
      + ZW_LIFE_ANIMAL_ORDER.map(function(hanKey) {
        var item = ZW_LIFE_ANIMAL_MAP[hanKey];
        if (!item) return '';
        var selected = primaryKey === hanKey;
        var border = selected ? '1.5px solid rgba(250,204,21,0.72)' : '1px solid rgba(148,163,184,0.24)';
        var glow = selected ? 'box-shadow:0 0 18px rgba(250,204,21,0.25)' : '';
        return ''
          + '<details style="border:' + border + ';' + glow + ';border-radius:10px;background:rgba(15,23,42,0.52);padding:8px">'
          + '<summary style="cursor:pointer;list-style:none;font-size:0.8rem;color:#f8fafc;font-weight:800;display:flex;align-items:center;justify-content:space-between;gap:8px">'
          + '<span>' + item.emoji + ' ' + _zwPortfolioEscapeHtml(item.animal) + ' · ' + _zwPortfolioEscapeHtml(item.koreanName) + '</span>'
          + '<span style="font-size:0.68rem;color:#c4b5fd">' + _zwPortfolioEscapeHtml(item.archetype) + '</span>'
          + '</summary>'
          + '<div style="margin-top:7px;font-size:0.75rem;color:#cbd5e1;line-height:1.55">'
          + '<div style="color:#fcd34d;font-weight:700">키워드: ' + _zwPortfolioEscapeHtml((item.keywords || []).slice(0, 4).join(' · ')) + '</div>'
          + '<div style="margin-top:5px">' + _zwPortfolioEscapeHtml(item.summary) + '</div>'
          + '</div>'
          + '</details>';
      }).join('')
      + '</div>';
  }

  function _zwBuildLifeAnimalCards(pd) {
    var resolved = _zwResolveLifeAnimal(pd);
    var titleLine = '명궁의 주성은 당신이 세상을 대하는 기본 자세를 보여줍니다.';
    var bridgeLine = '명궁 동물 해석은 명궁·신궁·재백궁·부부궁·관록궁·복덕궁을 함께 읽을 때 가장 정확하게 작동하는 보조 해석입니다.';

    if (!resolved || !resolved.primary) {
      return ''
        + '<div class="zw-detail-panel" id="zwLifeAnimalPanel">'
        + '  <div class="zw-dp-header">'
        + '    <div class="zw-dp-title">🌠 나의 명궁 동물</div>'
        + '    <div class="zw-dp-subtitle">명궁 주성으로 보는 나의 상징 동물</div>'
        + '  </div>'
        + '  <div class="zw-report-section" style="border-left-color:#64748b">'
        + '    <div class="zw-rtitle">🌫️ 숨은 동물 카드</div>'
        + '    <div class="zw-rdesc">명궁 주성을 확인할 수 없어 동물 상징을 계산하지 못했습니다. 공궁(空宮)인 경우에는 삼방사정에서 들어오는 별의 기운을 함께 확인해 주세요.</div>'
        + '  </div>'
        + '  <div style="margin-top:8px;font-size:0.79rem;color:#cbd5e1;line-height:1.65">'
        + _zwPortfolioEscapeHtml(titleLine + ' 명반에서 주성이 확인되면 자동으로 동물 프로필을 연결합니다. ' + bridgeLine)
        + '  </div>'
        + '  <div style="display:flex;flex-wrap:wrap;gap:7px;margin-top:10px">'
        + '    <button type="button" onclick="window._zwToggleAnimalCodex(\'zwLifeAnimalCodex\')" style="border:1px solid rgba(250,204,21,0.55);background:rgba(120,53,15,0.3);color:#fef3c7;border-radius:999px;padding:6px 10px;font-size:0.75rem;font-weight:700;cursor:pointer">14주성 동물 도감 보기</button>'
        + '    <button type="button" onclick="window._zwToggleAnimalCodex(\'zwLifeAnimalCodex\')" style="border:1px solid rgba(125,211,252,0.45);background:rgba(12,74,110,0.28);color:#dbeafe;border-radius:999px;padding:6px 10px;font-size:0.75rem;font-weight:700;cursor:pointer">다른 동물 보기</button>'
        + '    <button type="button" onclick="window._zwToggleAnimalCodex(\'zwLifeAnimalCodex\')" style="border:1px solid rgba(196,181,253,0.45);background:rgba(76,29,149,0.32);color:#ede9fe;border-radius:999px;padding:6px 10px;font-size:0.75rem;font-weight:700;cursor:pointer">내 안의 별동물 도감</button>'
        + '  </div>'
        + '  <details id="zwLifeAnimalCodex" style="margin-top:10px;border:1px solid rgba(196,181,253,0.3);border-radius:11px;background:rgba(15,23,42,0.42);padding:10px">'
        + '    <summary style="cursor:pointer;color:#fcd34d;font-size:0.82rem;font-weight:800">14주성 동물 도감 보기</summary>'
        + '    <div style="margin-top:9px">' + _zwBuildLifeAnimalCodex('') + '</div>'
        + '  </details>'
        + '</div>';
    }

    var primary = resolved.primary;
    var secondary = resolved.secondary;
    var insight = _zwBuildLifeAnimalInsight(primary, secondary, resolved);
    var pairLine = secondary
      ? ('대표 동물: ' + primary.emoji + ' ' + primary.animal + ' · 보조 동물: ' + secondary.emoji + ' ' + secondary.animal)
      : ('대표 동물: ' + primary.emoji + ' ' + primary.animal);
    var comboLine = secondary && resolved.comboText
      ? ('<div style="margin-top:8px;padding:8px;border-radius:9px;border:1px solid rgba(52,211,153,0.35);background:rgba(6,78,59,0.22);font-size:0.78rem;color:#d1fae5">'
        + '<b>주성 조합 해석</b>: ' + _zwPortfolioEscapeHtml(resolved.comboText)
        + '</div>')
      : '';
    var fallbackLine = resolved.fallbackNote
      ? ('<div style="margin-top:8px;padding:8px;border-radius:9px;border:1px solid rgba(251,191,36,0.38);background:rgba(120,53,15,0.24);font-size:0.77rem;color:#fde68a">'
        + _zwPortfolioEscapeHtml(resolved.fallbackNote)
        + '</div>')
      : '';

    return ''
      + '<div class="zw-detail-panel" id="zwLifeAnimalPanel">'
      + '  <div class="zw-dp-header">'
      + '    <div class="zw-dp-title">' + primary.emoji + ' 내 영혼을 상징하는 자미두수 동물</div>'
      + '    <div class="zw-dp-subtitle">명궁 주성으로 보는 나의 상징 동물 · 14주성 동물 프로필</div>'
      + '  </div>'
      + '  <div style="border:1px solid rgba(250,204,21,0.42);background:linear-gradient(145deg,rgba(24,24,62,0.92),rgba(12,26,58,0.92));border-radius:14px;padding:12px">'
      + '    <div style="font-size:0.95rem;color:#fef3c7;font-weight:900">' + primary.emoji + ' 나의 명궁 동물</div>'
      + '    <div style="margin-top:4px;font-size:0.88rem;color:#f8fafc;font-weight:800">' + _zwPortfolioEscapeHtml(primary.animal) + ' · ' + _zwPortfolioEscapeHtml(primary.koreanName) + '</div>'
      + '    <div style="margin-top:3px;font-size:0.76rem;color:#c4b5fd">' + _zwPortfolioEscapeHtml(primary.archetype) + ' / ' + _zwPortfolioEscapeHtml((primary.keywords || []).slice(0, 5).join(' · ')) + '</div>'
      + '    <div style="margin-top:7px;font-size:0.79rem;color:#dbeafe;line-height:1.6">당신의 명궁 동물은 ' + primary.emoji + ' ' + _zwPortfolioEscapeHtml(primary.animal) + '입니다. ' + _zwPortfolioEscapeHtml(primary.summary) + '</div>'
      + '    <div style="margin-top:7px;font-size:0.74rem;color:#fcd34d">주성: ' + _zwPortfolioEscapeHtml(primary.koreanName) + (secondary ? (' + ' + _zwPortfolioEscapeHtml(secondary.koreanName)) : '') + '</div>'
      + '    <div style="margin-top:6px;font-size:0.75rem;color:#e2e8f0">' + _zwPortfolioEscapeHtml(pairLine) + '</div>'
      + comboLine
      + fallbackLine
      + '    <details style="margin-top:9px;border:1px solid rgba(196,181,253,0.32);border-radius:10px;background:rgba(15,23,42,0.55);padding:9px">'
      + '      <summary style="cursor:pointer;color:#bae6fd;font-size:0.8rem;font-weight:800">자세히 보기</summary>'
      + '      <div style="margin-top:9px;display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px">'
      + '        <div style="font-size:0.78rem;color:#cbd5e1;line-height:1.62"><b style="color:#fcd34d">대표 동물</b><br>' + primary.emoji + ' ' + _zwPortfolioEscapeHtml(primary.animal) + '</div>'
      + '        <div style="font-size:0.78rem;color:#cbd5e1;line-height:1.62"><b style="color:#fcd34d">명궁 주성</b><br>' + _zwPortfolioEscapeHtml(primary.koreanName + (secondary ? (' + ' + secondary.koreanName) : '')) + '</div>'
      + '        <div style="font-size:0.78rem;color:#cbd5e1;line-height:1.62"><b style="color:#fcd34d">한 줄 요약</b><br>' + _zwPortfolioEscapeHtml(insight.oneLine) + '</div>'
      + '        <div style="font-size:0.78rem;color:#cbd5e1;line-height:1.62"><b style="color:#fcd34d">성격 핵심</b><br>' + _zwPortfolioEscapeHtml(insight.personalityCore) + '</div>'
      + '        <div style="font-size:0.78rem;color:#cbd5e1;line-height:1.62"><b style="color:#fcd34d">강점</b><br>' + _zwPortfolioEscapeHtml(insight.strengths) + '</div>'
      + '        <div style="font-size:0.78rem;color:#cbd5e1;line-height:1.62"><b style="color:#fcd34d">약점</b><br>' + _zwPortfolioEscapeHtml(insight.weaknesses) + '</div>'
      + '        <div style="font-size:0.78rem;color:#cbd5e1;line-height:1.62"><b style="color:#fcd34d">관계 스타일</b><br>' + _zwPortfolioEscapeHtml(insight.relationStyle) + '</div>'
      + '        <div style="font-size:0.78rem;color:#cbd5e1;line-height:1.62"><b style="color:#fcd34d">일/재물 스타일</b><br>' + _zwPortfolioEscapeHtml(insight.workMoneyStyle) + '</div>'
      + '        <div style="font-size:0.78rem;color:#cbd5e1;line-height:1.62"><b style="color:#fcd34d">오늘의 활용법</b><br>' + _zwPortfolioEscapeHtml(insight.todayTip) + '</div>'
      + '        <div style="font-size:0.78rem;color:#cbd5e1;line-height:1.62"><b style="color:#fcd34d">주의할 점</b><br>' + _zwPortfolioEscapeHtml(insight.caution) + '</div>'
      + '      </div>'
      + '      <div style="margin-top:10px;padding:9px;border-radius:9px;border:1px solid rgba(125,211,252,0.32);background:rgba(12,74,110,0.2);font-size:0.79rem;line-height:1.68;color:#e0f2fe">'
      + _zwPortfolioEscapeHtml(insight.longNarrative)
      + '      </div>'
      + '      <div style="margin-top:8px;padding:8px;border-radius:9px;background:rgba(76,29,149,0.26);border:1px solid rgba(196,181,253,0.35);font-size:0.78rem;color:#ede9fe">'
      + '다마고치식 한마디: “' + _zwPortfolioEscapeHtml(insight.tamagotchiLine) + '”'
      + '      </div>'
      + '    </details>'
      + '  </div>'
      + '  <div style="margin-top:9px;font-size:0.79rem;color:#cbd5e1;line-height:1.7">'
      + _zwPortfolioEscapeHtml(titleLine + ' 이 별을 동물 상징으로 바꾸면, 당신의 자미두수 동물은 ' + primary.animal + '입니다. ' + bridgeLine)
      + '  </div>'
      + '  <div style="display:flex;flex-wrap:wrap;gap:7px;margin-top:10px">'
      + '    <button type="button" onclick="window._zwToggleAnimalCodex(\'zwLifeAnimalCodex\')" style="border:1px solid rgba(250,204,21,0.55);background:rgba(120,53,15,0.3);color:#fef3c7;border-radius:999px;padding:6px 10px;font-size:0.75rem;font-weight:700;cursor:pointer">14주성 동물 도감 보기</button>'
      + '    <button type="button" onclick="window._zwToggleAnimalCodex(\'zwLifeAnimalCodex\')" style="border:1px solid rgba(125,211,252,0.45);background:rgba(12,74,110,0.28);color:#dbeafe;border-radius:999px;padding:6px 10px;font-size:0.75rem;font-weight:700;cursor:pointer">다른 동물 보기</button>'
      + '    <button type="button" onclick="window._zwToggleAnimalCodex(\'zwLifeAnimalCodex\')" style="border:1px solid rgba(196,181,253,0.45);background:rgba(76,29,149,0.32);color:#ede9fe;border-radius:999px;padding:6px 10px;font-size:0.75rem;font-weight:700;cursor:pointer">내 안의 별동물 도감</button>'
      + '  </div>'
      + '  <details id="zwLifeAnimalCodex" style="margin-top:10px;border:1px solid rgba(196,181,253,0.3);border-radius:11px;background:rgba(15,23,42,0.42);padding:10px">'
      + '    <summary style="cursor:pointer;color:#fcd34d;font-size:0.82rem;font-weight:800">14주성 동물 도감 보기</summary>'
      + '    <div style="margin-top:9px">' + _zwBuildLifeAnimalCodex(resolved.primaryKey) + '</div>'
      + '  </details>'
      + '</div>';
  }

  function _zwPortfolioBuildRows(pd) {
    var rows = [];
    for (var i = 0; i < 12; i += 1) {
      var palaceName = (pd.palacesByIndex && pd.palacesByIndex[i]) || ('제' + (i + 1) + '궁');
      var st = (pd.stars && pd.stars[i]) || { main: [], borrowedMain: [], aux: [], bad: [] };
      var mainRaw = (st.main && st.main.length) ? st.main : (st.borrowedMain || []);
      var mainStars = _zwPortfolioExtractStars(mainRaw);
      var auxStars = _zwPortfolioExtractStars(st.aux || []);
      var badStars = _zwPortfolioExtractStars(st.bad || []);
      var profile = _zwPortfolioProfileFromStars(mainStars.concat(auxStars));
      rows.push({
        idx: i,
        branch: ZHI_LIST[i] || '',
        palace: palaceName,
        palaceDisplay: ZW_PORTFOLIO_PALACE_ALIAS[palaceName] || palaceName,
        mainStars: mainStars,
        auxStars: auxStars,
        badStars: badStars,
        profile: profile
      });
    }
    return rows;
  }

  function _zwPortfolioBuildSummary(rows) {
    var score = {};
    rows.forEach(function(row){
      var star = (row.mainStars && row.mainStars[0]) || row.profile.anchor;
      score[star] = (score[star] || 0) + 1;
    });
    var dominant = Object.keys(score).sort(function(a, b){ return score[b] - score[a]; })[0] || '자미';
    var titleObj = ZW_PORTFOLIO_MAIN_TITLE[dominant] || ZW_PORTFOLIO_MAIN_TITLE['자미'];
    var dominantProfile = ZW_PORTFOLIO_STAR_PROFILE[dominant] || ZW_PORTFOLIO_STAR_PROFILE['자미'];
    return {
      dominantStar: dominant,
      title: titleObj.title,
      slogan: titleObj.slogan,
      symbol: titleObj.symbol,
      hash: dominantProfile.persona,
      keywords: dominantProfile.keywords || []
    };
  }

  function _zwBuildBasicCanonicalCards(pd) {
    if (!pd || !Array.isArray(pd.palaceStarData) || !pd.palaceStarData.length) return '';

    var palaceMap = {};
    pd.palaceStarData.forEach(function(row){
      if (row && row.palace) palaceMap[row.palace] = row;
    });

    function _zwBasicStars(row) {
      if (!row) return '데이터 없음';
      var mains = _zwPortfolioExtractStars(row.stars || []).slice(0, 2);
      if (!mains.length) mains = _zwPortfolioExtractStars(row.auxStars || []).slice(0, 2);
      return mains.length ? mains.join(' · ') : '공궁(空宮)';
    }

    var sihuaCount = { '화록': 0, '화권': 0, '화과': 0, '화기': 0 };
    pd.palaceStarData.forEach(function(row){
      var merged = [].concat((row && row.stars) || [], (row && row.auxStars) || [], (row && row.badStars) || []);
      merged.forEach(function(raw){
        var starName = (raw && typeof raw === 'object') ? (raw.name || '') : String(raw || '');
        var hit = starName.match(/화록|화권|화과|화기/);
        if (hit && Object.prototype.hasOwnProperty.call(sihuaCount, hit[0])) sihuaCount[hit[0]] += 1;
      });
    });

    var sihuaGuide = {
      '화록': '자원과 기회가 모이는 방식입니다. 반복 가능한 구조를 만들수록 장점이 오래 갑니다.',
      '화권': '주도권과 책임을 다루는 방식입니다. 역할 경계를 분명히 할수록 힘이 안정됩니다.',
      '화과': '평판과 전문성이 드러나는 방식입니다. 기록, 신뢰, 공개 성과가 운을 밝힙니다.',
      '화기': '마찰과 집착이 생기기 쉬운 지점입니다. 일정·관계·재정의 완충 규칙이 필요합니다.'
    };
    var sihuaGuideLines = ['화록','화권','화과','화기'].map(function(key){
      return '<b>'+_zwPortfolioEscapeHtml(key)+'</b>: '+_zwPortfolioEscapeHtml(sihuaGuide[key]);
    }).join('<br>');

    var keyPalaces = ['명궁', '관록궁', '재백궁', '부부궁', '복덕궁'];
    var keyRowsHtml = keyPalaces.map(function(name){
      var row = palaceMap[name];
      if (!row) return '';
      var stars = _zwBasicStars(row);
      var profile = _zwPortfolioProfileFromStars(_zwPortfolioExtractStars((row.stars || []).concat(row.auxStars || [])));
      return '<div style="display:flex;justify-content:space-between;gap:10px;padding:6px 0;border-bottom:1px solid rgba(148,163,184,0.12)">'
        + '<span style="color:#c4b5fd;font-size:0.79rem;white-space:nowrap">'+_zwPortfolioEscapeHtml(name)+'</span>'
        + '<span style="color:#f8fafc;font-size:0.8rem;text-align:right">'+_zwPortfolioEscapeHtml(stars)+'<br><span style="color:#93c5fd;font-size:0.72rem">'+_zwPortfolioEscapeHtml(profile.persona)+'</span></span>'
        + '</div>';
    }).join('');

    var baseMeta = pd.calcMeta
      ? ('음력 ' + pd.calcMeta.lunarMonth + '월 ' + pd.calcMeta.lunarDay + '일 · 시지 ' + pd.calcMeta.hourBranch)
      : '명반 기준 정보 없음';

    return ''
      + '<div class="zw-detail-panel" id="zwBasicCanonicalPanel">'
      + '  <div class="zw-dp-header">'
      + '    <div class="zw-dp-title">🧩 기본 명반 핵심 카드</div>'
      + '    <div class="zw-dp-subtitle">12궁 핵심 신호를 기본 명반 흐름으로 정리 · '+_zwPortfolioEscapeHtml(baseMeta)+'</div>'
      + '  </div>'
      + '  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px">'
      + '    <div class="zw-report-section" style="border-left-color:#f59e0b">'
      + '      <div class="zw-rtitle">🌕 명주 코어</div>'
      + '      <div class="zw-rdesc">명궁 <b>'+_zwPortfolioEscapeHtml(String(pd.meng || '-'))+'</b> · 신궁 <b>'+_zwPortfolioEscapeHtml(String(pd.shen || '-'))+'</b> · 오행국 <b>'+_zwPortfolioEscapeHtml(String(pd.juInfo || '-'))+'</b> 조합은 기본 성향 축을 형성합니다.</div>'
      + '    </div>'
      + '    <div class="zw-report-section" style="border-left-color:#38bdf8">'
      + '      <div class="zw-rtitle">🏛 핵심 궁 포트폴리오</div>'
      + '      <div class="zw-rdesc">'+(keyRowsHtml || '핵심 궁 데이터를 불러오는 중입니다.')+'</div>'
      + '    </div>'
      + '    <div class="zw-report-section" style="border-left-color:#a78bfa">'
      + '      <div class="zw-rtitle">⚡ 사화(四化) 신호</div>'
      + '      <div class="zw-rdesc">화록 '+sihuaCount['화록']+' · 화권 '+sihuaCount['화권']+' · 화과 '+sihuaCount['화과']+' · 화기 '+sihuaCount['화기']+'<br>'+sihuaGuideLines+'</div>'
      + '    </div>'
      + '    <div class="zw-report-section" style="border-left-color:#34d399">'
      + '      <div class="zw-rtitle">🧭 생활 가이드</div>'
      + '      <div class="zw-rdesc">관록궁·재백궁 카드에서 반복 키워드를 먼저 살피고, 부부궁·복덕궁 신호로 관계와 정서 리듬을 보정하면 명반 해석의 균형이 선명해집니다.</div>'
      + '    </div>'
      + '  </div>'
      + '</div>';
  }

  function _zwBuildDeepCanonicalPayload(pd) {
    if (!pd || !Array.isArray(pd.palaceStarData) || !pd.palaceStarData.length) return null;

    var rows = pd.palaceStarData.map(function(row, idx) {
      var mainStars = _zwPortfolioExtractStars((row && row.stars) || []);
      var auxStars = _zwPortfolioExtractStars((row && row.auxStars) || []);
      var badStars = _zwPortfolioExtractStars((row && row.badStars) || []);
      var mergedRaw = [].concat((row && row.stars) || [], (row && row.auxStars) || [], (row && row.badStars) || []);
      var sihua = '';
      for (var i = 0; i < mergedRaw.length; i += 1) {
        var raw = mergedRaw[i];
        if (raw && typeof raw === 'object' && raw.sihua) {
          sihua = raw.sihua;
          break;
        }
      }
      var borrowed = ((row && row.stars) || []).some(function(raw) {
        return /\(차성\)|\b차성\b/.test(String(raw || ''));
      });
      var profile = _zwPortfolioProfileFromStars(mainStars.concat(auxStars));
      var score = Math.round(
        mainStars.length * 18
        + auxStars.length * 7
        - badStars.length * 9
        + (sihua === '화록' ? 8 : sihua === '화권' ? 6 : sihua === '화과' ? 5 : sihua === '화기' ? -10 : 0)
        + (borrowed ? -3 : 0)
      );
      return {
        idx: idx,
        palace: (row && row.palace) || ((pd.palacesByIndex && pd.palacesByIndex[idx]) || ('제' + (idx + 1) + '궁')),
        branch: (row && row.branch) || (ZHI_LIST[idx] || ''),
        dahan: (row && row.dahan) || ((pd.daHanList && pd.daHanList[idx]) || ''),
        mainStars: mainStars,
        auxStars: auxStars,
        badStars: badStars,
        sihua: sihua,
        borrowed: borrowed,
        profile: profile,
        score: score,
        riskScore: Math.round(badStars.length * 12 + (sihua === '화기' ? 10 : 0) + (borrowed ? 3 : 0) - mainStars.length * 2)
      };
    });

    var topPalaces = rows.slice().sort(function(a, b) {
      return b.score - a.score;
    }).slice(0, 4);

    var riskPalaces = rows.slice().sort(function(a, b) {
      return b.riskScore - a.riskScore;
    }).slice(0, 4);

    var sihuaCount = { '화록': 0, '화권': 0, '화과': 0, '화기': 0 };
    rows.forEach(function(row) {
      if (row.sihua && Object.prototype.hasOwnProperty.call(sihuaCount, row.sihua)) {
        sihuaCount[row.sihua] += 1;
      }
    });

    var dominantSihua = Object.keys(sihuaCount).sort(function(a, b) {
      return sihuaCount[b] - sihuaCount[a];
    })[0] || '화록';

    var decadeFlow = (Array.isArray(pd.daHanList) ? pd.daHanList : []).slice(0, 8).map(function(period, idx) {
      var row = rows[idx % rows.length];
      return {
        period: period,
        palace: row ? row.palace : '',
        profile: row && row.profile ? row.profile.persona : '',
        mainStars: row && row.mainStars ? row.mainStars.slice(0, 2) : [],
        focus: row && row.mainStars && row.mainStars.length
          ? row.mainStars[0] + ' 중심 실행'
          : '관찰 기반 조정'
      };
    });

    var keywords = [];
    topPalaces.forEach(function(row) {
      (row.profile && row.profile.keywords ? row.profile.keywords : []).forEach(function(k) {
        if (k && keywords.indexOf(k) < 0) keywords.push(k);
      });
    });

    return {
      core: {
        meng: pd.meng || '',
        shen: pd.shen || '',
        juInfo: pd.juInfo || '',
        calcMeta: pd.calcMeta || null
      },
      topPalaces: topPalaces,
      riskPalaces: riskPalaces,
      sihua: {
        count: sihuaCount,
        dominant: dominantSihua
      },
      decadeFlow: decadeFlow,
      keywords: keywords.slice(0, 8)
    };
  }

  function _zwBuildDeepCanonicalCards(pd) {
    var payload = _zwBuildDeepCanonicalPayload(pd);
    if (!payload) return '';

    var topHtml = payload.topPalaces.map(function(row, idx) {
      var stars = row.mainStars.length ? row.mainStars.slice(0, 2).join(' · ') : '공궁(空宮)';
      var persona = String(row.profile.persona || '');
      return '<div style="display:flex;justify-content:space-between;gap:10px;padding:6px 0;border-bottom:1px solid rgba(148,163,184,0.12)">'
        + '<span style="color:#a5b4fc;font-size:0.79rem;white-space:nowrap">TOP ' + (idx + 1) + ' · ' + _zwPortfolioEscapeHtml(String(row.palace || '-')) + '</span>'
        + '<span style="color:#f8fafc;font-size:0.8rem;text-align:right">' + _zwPortfolioEscapeHtml(stars) + '<br><span style="color:#93c5fd;font-size:0.72rem">' + _zwPortfolioEscapeHtml(persona) + '</span></span>'
        + '</div>';
    }).join('');

    var riskHtml = payload.riskPalaces.map(function(row, idx) {
      var flags = [];
      if (row.sihua) flags.push(row.sihua);
      if (row.badStars.length) flags.push('흉성 ' + row.badStars.length);
      if (row.borrowed) flags.push('차성');
      return '<div style="display:flex;justify-content:space-between;gap:10px;padding:6px 0;border-bottom:1px solid rgba(248,113,113,0.14)">'
        + '<span style="color:#fda4af;font-size:0.79rem;white-space:nowrap">주의 ' + (idx + 1) + ' · ' + _zwPortfolioEscapeHtml(String(row.palace || '-')) + '</span>'
        + '<span style="color:#fecaca;font-size:0.77rem;text-align:right">' + _zwPortfolioEscapeHtml(flags.join(' · ') || '기초 점검') + '</span>'
        + '</div>';
    }).join('');

    var decadeHtml = payload.decadeFlow.slice(0, 5).map(function(row) {
      var periodText = (row.period && typeof row.period === 'object')
        ? (row.period.startAge + '세~')
        : String(row.period || '-');
      return '<div style="display:flex;justify-content:space-between;gap:10px;padding:6px 0;border-bottom:1px solid rgba(147,197,253,0.14)">'
        + '<span style="color:#bae6fd;font-size:0.78rem;white-space:nowrap">' + _zwPortfolioEscapeHtml(periodText) + '</span>'
        + '<span style="color:#e2e8f0;font-size:0.77rem;text-align:right">' + _zwPortfolioEscapeHtml(String(row.palace || '-')) + ' · ' + _zwPortfolioEscapeHtml(String(row.focus || '')) + '</span>'
        + '</div>';
    }).join('');

    var keywordText = payload.keywords.length ? payload.keywords.join(' · ') : '균형 · 실행 · 리스크 관리';

    return ''
      + '<div class="zw-detail-panel" id="zwDeepCanonicalPanel">'
      + '  <div class="zw-dp-header">'
      + '    <div class="zw-dp-title">🛰 자미두수 심화 해석 레이어</div>'
      + '    <div class="zw-dp-subtitle">궁별 점수·사화·대운 흐름을 합성한 심화 데이터</div>'
      + '  </div>'
      + '  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px">'
      + '    <div class="zw-report-section" style="border-left-color:#60a5fa">'
      + '      <div class="zw-rtitle">🏆 고신뢰 궁 TOP</div>'
      + '      <div class="zw-rdesc">' + (topHtml || '데이터 없음') + '</div>'
      + '    </div>'
      + '    <div class="zw-report-section" style="border-left-color:#fb7185">'
      + '      <div class="zw-rtitle">🛑 리스크 경계 궁</div>'
      + '      <div class="zw-rdesc">' + (riskHtml || '리스크 신호 없음') + '</div>'
      + '    </div>'
      + '    <div class="zw-report-section" style="border-left-color:#22d3ee">'
      + '      <div class="zw-rtitle">⏳ 대운 핵심 리듬</div>'
      + '      <div class="zw-rdesc">' + (decadeHtml || '대운 정보 없음') + '</div>'
      + '    </div>'
      + '    <div class="zw-report-section" style="border-left-color:#a78bfa">'
      + '      <div class="zw-rtitle">🎯 정밀 키워드 & 사화축</div>'
      + '      <div class="zw-rdesc">핵심 키워드: <b>' + _zwPortfolioEscapeHtml(keywordText) + '</b><br>사화 분포: 화록 ' + payload.sihua.count['화록'] + ' · 화권 ' + payload.sihua.count['화권'] + ' · 화과 ' + payload.sihua.count['화과'] + ' · 화기 ' + payload.sihua.count['화기'] + '<br>현재 주축: <b>' + _zwPortfolioEscapeHtml(payload.sihua.dominant) + '</b></div>'
      + '    </div>'
      + '  </div>'
      + '</div>';
  }

  var _ZW_AI_PROMPT_COST = 100;
  var _ZW_AI_PROMPT_MAX_LENGTH = 1000;
  var _ZW_AI_PROMPT_MIN_LENGTH = 5;
  var _ZW_AI_PROMPT_FEATURE_KEY = 'ziwei_ai_prompt_generator';
  var _ZW_AI_PROMPT_REASON = '자미두수 AI 질문 프롬프트 생성';
  var _ZW_AI_PROMPT_REQUEST_PREFIX = 'ziwei-ai-prompt:';

  function _zwPromptPalaceIdFromName(name) {
    var map = {
      '명궁': 'ming',
      '형제궁': 'siblings',
      '부부궁': 'spouse',
      '자녀궁': 'children',
      '재백궁': 'wealth',
      '질액궁': 'health',
      '천이궁': 'travel',
      '노복궁': 'friends',
      '교우궁': 'friends',
      '관록궁': 'career',
      '전택궁': 'property',
      '복덕궁': 'fortune',
      '부모궁': 'parents'
    };
    var key = String(name || '').trim();
    return map[key] || '';
  }

  function _zwPromptNormalizeStar(raw) {
    if (raw && typeof raw === 'object') {
      var objName = String(raw.name || '').trim();
      if (!objName) return null;
      return {
        name: objName,
        strengthSymbol: String(raw.strengthSymbol || raw.symbol || '').trim()
      };
    }
    var text = String(raw || '')
      .replace(/<[^>]*>/g, '')
      .replace(/\s+/g, ' ')
      .trim();
    if (!text) return null;
    var symbolMatch = text.match(/[◎○△×]/);
    var symbol = symbolMatch ? symbolMatch[0] : '';
    var name = text
      .replace(/[◎○△×]/g, '')
      .replace(/\(차성\)/g, '')
      .trim();
    if (!name) return null;
    return {
      name: name,
      strengthSymbol: symbol
    };
  }

  function _zwPromptNormalizeStarList(list) {
    if (!Array.isArray(list)) return [];
    return list
      .map(function(item) { return _zwPromptNormalizeStar(item); })
      .filter(function(item) { return !!item && !!item.name; });
  }

  function _zwPromptPushUnique(list, value) {
    var text = String(value || '').trim();
    if (!text || list.indexOf(text) >= 0) return;
    list.push(text);
  }

  function _zwPromptFormatDahanRange(period) {
    if (!period || typeof period !== 'object') return String(period || '').trim();
    var startAge = Number(period.startAge);
    var endAge = Number(period.endAge);
    if (Number.isFinite(startAge) && Number.isFinite(endAge)) {
      return String(Math.trunc(startAge)) + '~' + String(Math.trunc(endAge)) + '세';
    }
    return String(period.label || period.range || '').trim();
  }

  function _zwPromptBuildSihua(pd) {
    var result = { hualu: '', huaquan: '', huake: '', huaji: '' };
    var keyByType = { '화록': 'hualu', '화권': 'huaquan', '화과': 'huake', '화기': 'huaji' };
    if (pd && pd.sihuaData && typeof pd.sihuaData === 'object') {
      Object.keys(pd.sihuaData).forEach(function(starName) {
        var item = pd.sihuaData[starName] || {};
        var key = keyByType[String(item.type || '').trim()];
        if (!key || result[key]) return;
        var palaceName = String(item.palaceName || '').trim();
        result[key] = String(starName || '').trim() + (palaceName ? ' (' + palaceName + ')' : '');
      });
    }
    var raw = (pd && pd.sihua && typeof pd.sihua === 'object') ? pd.sihua : {};
    result.hualu = result.hualu || String(raw.hualu || raw.luk || '').trim();
    result.huaquan = result.huaquan || String(raw.huaquan || raw.quan || '').trim();
    result.huake = result.huake || String(raw.huake || raw.ke || '').trim();
    result.huaji = result.huaji || String(raw.huaji || raw.ji || '').trim();
    return result;
  }

  function _zwPromptGanji(year) {
    var gan = ['甲','乙','丙','丁','戊','己','庚','辛','壬','癸'];
    var zhi = ['子','丑','寅','卯','辰','巳','午','未','申','酉','戌','亥'];
    var offset = Number(year) - 1984;
    if (!Number.isFinite(offset)) return '';
    return gan[((offset % 10) + 10) % 10] + zhi[((offset % 12) + 12) % 12];
  }

  function _zwPromptBuildAnnualFlow(pd, majorPeriods) {
    var year = new Date().getFullYear();
    var ganji = _zwPromptGanji(year);
    var yearZhi = ganji.charAt(1);
    var keyPalaces = [];
    var notes = [];
    var anchorIdx = (typeof ZHI_LIST !== 'undefined' && yearZhi) ? ZHI_LIST.indexOf(yearZhi) : -1;
    if (anchorIdx >= 0 && pd && pd.palacesByIndex) {
      _zwPromptPushUnique(keyPalaces, _zwPromptPalaceIdFromName(pd.palacesByIndex[anchorIdx]));
      notes.push(String(year) + '년 ' + ganji + ' 기준 유년 기준궁: ' + String(pd.palacesByIndex[anchorIdx] || '').trim());
    }
    if (pd && pd.sihuaData && typeof pd.sihuaData === 'object') {
      Object.keys(pd.sihuaData).forEach(function(starName) {
        var item = pd.sihuaData[starName] || {};
        var palaceName = String(item.palaceName || '').trim();
        _zwPromptPushUnique(keyPalaces, _zwPromptPalaceIdFromName(palaceName));
        if (starName && item.type && palaceName) notes.push(String(item.type) + ' ' + String(starName) + ' 작동궁: ' + palaceName);
      });
    }
    if (majorPeriods && majorPeriods.length) {
      var first = majorPeriods[0] || {};
      notes.push('대한 기준: ' + String(first.range || '').trim() + ' · ' + String(first.palaceName || '').trim());
    }
    return {
      yearLabel: String(year) + '년' + (ganji ? ' ' + ganji : ''),
      keyPalaces: keyPalaces.filter(Boolean).slice(0, 4),
      notes: notes.filter(Boolean).slice(0, 6)
    };
  }

  function _zwGetPromptProfile() {
    try {
      if (window.__cdActiveBirthProfile && window.__cdActiveBirthProfile.birth) return window.__cdActiveBirthProfile;
    } catch (_) {}
    try {
      if (window.__destinyFlowerSajuSnapshot && window.__destinyFlowerSajuSnapshot.birth) return window.__destinyFlowerSajuSnapshot;
    } catch (_) {}
    return null;
  }

  function _zwPromptFirstText(values) {
    if (!Array.isArray(values)) return '';
    for (var i = 0; i < values.length; i += 1) {
      var text = String(values[i] == null ? '' : values[i]).trim();
      if (text) return text;
    }
    return '';
  }

  function _zwPromptTimezoneText(raw) {
    if (raw == null || raw === '') return '';
    var num = Number(raw);
    if (Number.isFinite(num)) return 'UTC' + (num >= 0 ? '+' : '') + String(num);
    return String(raw || '').trim();
  }

  function _zwBuildPromptChartResult(pd) {
    var birth = window._ziweiBirth || {};
    var profile = _zwGetPromptProfile();
    var profileBirth = (profile && profile.birth) ? profile.birth : {};
    var rawGender = String((profile && profile.gender) || '').trim().toLowerCase();
    var normalizedGender = '';
    if (rawGender === 'm' || rawGender === 'male' || rawGender.indexOf('남') === 0) normalizedGender = 'M';
    if (rawGender === 'f' || rawGender === 'female' || rawGender.indexOf('여') === 0) normalizedGender = 'F';
    var calendarType = String(profileBirth.calendarType || profileBirth.calendar || 'solar').toLowerCase() === 'lunar' ? 'lunar' : 'solar';
    var unknownHour = profileBirth.unknownHour === true || birth.unknownHour === true;
    var birthPlace = _zwPromptFirstText([
      profileBirth.birthPlace,
      profileBirth.place,
      profileBirth.locationName,
      profile && profile.birthPlace,
      birth.birthPlace,
      birth.place,
      birth.locationName
    ]);
    var timezone = _zwPromptFirstText([
      _zwPromptTimezoneText(profileBirth.timezone),
      _zwPromptTimezoneText(profileBirth.tzName),
      _zwPromptTimezoneText(profile && profile.timezone),
      _zwPromptTimezoneText(birth.timezone),
      _zwPromptTimezoneText(birth.tzName),
      _zwPromptTimezoneText(birth.tz)
    ]);
    var user = {
      name: (profile && profile.name) ? String(profile.name) : '',
      gender: normalizedGender,
      birthYear: Number(profileBirth.year || birth.year || 0) || undefined,
      birthMonth: Number(profileBirth.month || birth.month || 0) || undefined,
      birthDay: Number(profileBirth.day || birth.day || 0) || undefined,
      birthHour: Number(profileBirth.hour || birth.hour || 0) || undefined,
      birthMinute: Number(profileBirth.minute || birth.minute || 0) || undefined,
      calendarType: calendarType,
      unknownHour: unknownHour,
      birthPlace: birthPlace,
      timezone: timezone
    };

    var palaceRows = Array.isArray(pd && pd.palaceStarData) ? pd.palaceStarData : [];
    var palaces = palaceRows.map(function(row, idx) {
      var palaceName = String((row && row.palace) || ((pd && pd.palacesByIndex && pd.palacesByIndex[idx]) || '')).trim();
      var palaceId = _zwPromptPalaceIdFromName(palaceName);
      return {
        id: palaceId,
        name: palaceName,
        branch: String((row && row.branch) || (ZHI_LIST[idx] || '')).trim(),
        mainStars: _zwPromptNormalizeStarList((row && row.stars) || []),
        auxiliaryStars: _zwPromptNormalizeStarList((row && row.auxStars) || []),
        strengthSummary: {
          weakStars: _zwPromptNormalizeStarList((row && row.badStars) || [])
        },
        index: idx
      };
    });

    var majorPeriods = Array.isArray(pd && pd.daHanList)
      ? pd.daHanList.map(function(period, idx) {
        var palaceIdx = period && typeof period === 'object' && Number.isFinite(Number(period.idx)) ? Number(period.idx) : idx;
        var palaceName = (period && period.palaceName) || (pd && pd.palacesByIndex && pd.palacesByIndex[palaceIdx]) || '';
        return {
          palaceId: _zwPromptPalaceIdFromName(palaceName),
          palaceName: String(palaceName || '').trim(),
          range: _zwPromptFormatDahanRange(period)
        };
      })
      : [];
    var promptSihua = _zwPromptBuildSihua(pd);
    var annualFlow = _zwPromptBuildAnnualFlow(pd, majorPeriods);

    var summaryDirection = '';
    if (pd && typeof pd.meng !== 'undefined' && typeof pd.shen !== 'undefined') {
      summaryDirection = '명궁 ' + String(pd.meng || '-') + ' · 신궁 ' + String(pd.shen || '-') + ' 축 중심';
    }

    return {
      user: user,
      mingGong: String((pd && pd.meng) || ''),
      shenGong: String((pd && pd.shen) || ''),
      yearGan: String((pd && pd.yearGan) || ''),
      juInfo: String((pd && pd.juInfo) || ''),
      summary: {
        direction: summaryDirection,
        strengths: [],
        weaknesses: []
      },
      sihua: promptSihua,
      majorPeriods: majorPeriods,
      annualFlow: annualFlow,
      sihuaData: (pd && pd.sihuaData) || {},
      daHanList: Array.isArray(pd && pd.daHanList) ? pd.daHanList : [],
      palaces: palaces
    };
  }

  function _zwCopyTextSafe(text) {
    var str = String(text || '');
    if (!str) return Promise.reject(new Error('empty'));
    if (navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(str);
    }
    return new Promise(function(resolve, reject) {
      try {
        var ta = document.createElement('textarea');
        ta.value = str;
        ta.setAttribute('readonly', 'readonly');
        ta.style.position = 'fixed';
        ta.style.left = '-9999px';
        document.body.appendChild(ta);
        ta.select();
        var ok = document.execCommand('copy');
        document.body.removeChild(ta);
        if (ok) resolve();
        else reject(new Error('copy-failed'));
      } catch (e) {
        reject(e);
      }
    });
  }

  function _zwBuildDeepAiPromptPanel() {
    return ''
      + '<div class="zw-detail-panel" id="zwDeepAiPromptPanel" style="border:1px solid rgba(192,132,252,0.32);background:radial-gradient(140% 130% at 8% 0%, rgba(168,85,247,0.2), transparent 44%), radial-gradient(130% 130% at 100% 100%, rgba(16,185,129,0.18), transparent 40%), linear-gradient(145deg,rgba(24,24,55,0.93),rgba(8,20,28,0.92));box-shadow:0 24px 50px rgba(88,28,135,0.34), inset 0 1px 0 rgba(255,255,255,0.07);border-radius:16px;">'
      + '  <div class="zw-dp-header">'
      + '    <div class="zw-dp-title" style="color:#f5d0fe">👑 자미두수 궁성 맞춤 AI 상담</div>'
      + '    <div class="zw-dp-subtitle" style="color:#e9d5ff">기본 명반 데이터를 바탕으로 질문에 대한 맞춤 상담 답변을 바로 생성해 드립니다. (1회 10,000원)</div>'
      + '  </div>'
      + '  <div style="font-size:0.78rem;line-height:1.62;color:#e9d5ff;margin-bottom:10px">'
      + '    연애, 소송, 직업, 돈, 인간관계, 건강, 인생 방향 질문을 입력하면 질문 분류+명반 핵심궁을 반영한 상담 답변을 드립니다.'
      + '  </div>'
      + '  <div style="font-size:0.74rem;line-height:1.58;color:#fef3c7;background:rgba(120,53,15,0.3);border:1px solid rgba(251,191,36,0.32);border-radius:10px;padding:8px 10px;margin-bottom:10px">'
      + '    답변 생성에는 명반 요약이 사용됩니다. 답변과 함께 상담에 쓰인 프롬프트도 추가 비용 없이 아래에 제공됩니다.'
      + '  </div>'
      + '  <textarea id="zwDeepAiPromptQuestion" maxlength="1000" placeholder="' + _sajuEngineText("se_17711_attr_placeholder") + '" style="width:100%;min-height:122px;border-radius:12px;border:1px solid rgba(196,181,253,0.48);background:rgba(10,15,30,0.72);color:#f5f3ff;padding:12px;font-size:0.8rem;line-height:1.65;resize:vertical;box-sizing:border-box;"></textarea>'
      + '  <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-top:8px;font-size:0.74rem;color:#ddd6fe">'
      + '    <span id="zwDeepAiPromptCount">0 / 1000</span>'
      + '    <span>1회 10,000원</span>'
      + '  </div>'
      + '  <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:9px">'
      + '    <button id="zwDeepAiPromptGenerateBtn" type="button" style="background:linear-gradient(135deg,#f59e0b,#fbbf24,#7dd3fc);color:#172554;border:1px solid rgba(251,191,36,0.76);padding:9px 13px;border-radius:10px;font-size:0.8rem;font-weight:900;cursor:pointer;box-shadow:0 10px 22px rgba(251,191,36,0.28);">10,000원으로 AI 상담 받기</button>'
      + '    <button id="zwDeepAiPromptRegenerateBtn" type="button" style="display:none;background:linear-gradient(135deg,#1d4ed8,#312e81);color:#fff;border:1px solid rgba(147,197,253,0.75);padding:8px 12px;border-radius:10px;font-size:0.78rem;font-weight:700;cursor:pointer;">다시 상담 받기</button>'
      + '    <button id="zwDeepAiPromptCopyBtn" type="button" style="display:none;background:linear-gradient(135deg,#6d28d9,#4338ca);color:#fff;border:1px solid rgba(196,181,253,0.7);padding:8px 12px;border-radius:10px;font-size:0.78rem;font-weight:700;cursor:pointer;">프롬프트 복사</button>'
      + '  </div>'
      + '  <div id="zwDeepAiAnswer" style="display:none;margin-top:12px;padding:15px 16px;border-radius:14px;border:1px solid rgba(52,211,153,0.3);background:linear-gradient(160deg,rgba(6,20,30,0.78),rgba(20,14,44,0.72));overflow-wrap:anywhere;"></div>'
      + '  <details id="zwDeepAiPromptWrap" style="display:none;margin-top:12px;border:1px solid rgba(196,181,253,0.28);border-radius:12px;padding:8px 12px;background:rgba(10,15,30,0.5);">'
      + '    <summary style="cursor:pointer;font-size:0.78rem;font-weight:800;color:#c4b5fd;">📋 이 상담에 쓰인 프롬프트 보기 (무료 제공)</summary>'
      + '    <div style="font-size:0.72rem;color:#e9d5ff;margin:8px 0 4px;line-height:1.55">원하는 다른 AI에도 그대로 붙여 넣어 다시 활용할 수 있어요.</div>'
      + '    <textarea id="zwDeepAiPromptText" readonly style="margin-top:6px;width:100%;min-height:180px;border-radius:12px;border:1px solid rgba(52,211,153,0.42);background:rgba(2,24,19,0.56);color:#ecfdf5;padding:12px;font-size:0.78rem;line-height:1.6;resize:vertical;box-sizing:border-box;"></textarea>'
      + '  </details>'
      + '  <div id="zwDeepAiPromptStatus" style="margin-top:8px;font-size:0.76rem;color:#ddd6fe;"></div>'
      + '</div>';
  }

  function _zwInitDeepAiPromptPanel(panelId, pd) {
    var panel = document.getElementById(panelId);
    if (!panel || !pd) return;

    var chartResult = _zwBuildPromptChartResult(pd);
    var questionEl = panel.querySelector('#zwDeepAiPromptQuestion');
    var countEl = panel.querySelector('#zwDeepAiPromptCount');
    var statusEl = panel.querySelector('#zwDeepAiPromptStatus');
    var outputEl = panel.querySelector('#zwDeepAiPromptText');
    var answerEl = panel.querySelector('#zwDeepAiAnswer');
    var promptWrap = panel.querySelector('#zwDeepAiPromptWrap');
    var generateBtn = panel.querySelector('#zwDeepAiPromptGenerateBtn');
    var regenerateBtn = panel.querySelector('#zwDeepAiPromptRegenerateBtn');
    var copyBtn = panel.querySelector('#zwDeepAiPromptCopyBtn');

    if (!questionEl || !statusEl || !outputEl || !generateBtn || !regenerateBtn || !copyBtn) return;

    var isLoading = false;
    var zwEvidenceStore = _cdAIPromptEvidenceStore();
    // 생성 성공 시에만 올린다. 실패 재시도는 같은 requestId(재결제 없음), 성공 후 재요청은 새 결제.
    var zwRequestEpoch = 0;
    var zwRetryFree = false;

    function setStatus(message, tone) {
      statusEl.textContent = String(message || '');
      if (tone === 'error') {
        statusEl.style.color = '#fda4af';
      } else if (tone === 'success') {
        statusEl.style.color = '#86efac';
      } else {
        statusEl.style.color = '#b4a6d8';
      }
    }

    function setLoading(nextLoading) {
      isLoading = !!nextLoading;
      generateBtn.disabled = isLoading;
      regenerateBtn.disabled = isLoading;
      questionEl.disabled = isLoading;
      generateBtn.textContent = isLoading
        ? 'AI 상담 생성 중...'
        : (zwRetryFree
          ? '추가 결제 없이 다시 상담 받기'
          : (_ZW_AI_PROMPT_COST * 100).toLocaleString('ko-KR') + '원으로 AI 상담 받기');
      generateBtn.style.opacity = isLoading ? '0.7' : '1';
      regenerateBtn.style.opacity = isLoading ? '0.7' : '1';
    }

    function updateCount() {
      var len = String(questionEl.value || '').trim().length;
      if (countEl) countEl.textContent = len + ' / ' + _ZW_AI_PROMPT_MAX_LENGTH;
    }

    function buildHeaders() {
      var headers = { 'Content-Type': 'application/json' };
      try {
        var token = localStorage.getItem('fortune_auth_token');
        if (token) headers.Authorization = 'Bearer ' + token;
      } catch (_) {}
      return headers;
    }

    function handleGenerate(options) {
      if (isLoading) return;
      var opts = options && options.paymentPayload ? options : {};
      var paidPayload = opts.paymentPayload && typeof opts.paymentPayload === 'object' ? opts.paymentPayload : null;
      var question = String(questionEl.value || '').trim();
      if (!question || question.length < _ZW_AI_PROMPT_MIN_LENGTH) {
        setStatus('질문은 최소 ' + _ZW_AI_PROMPT_MIN_LENGTH + '자 이상 입력해 주세요.', 'error');
        return;
      }
      if (question.length > _ZW_AI_PROMPT_MAX_LENGTH) {
        setStatus('질문은 최대 ' + _ZW_AI_PROMPT_MAX_LENGTH + '자까지 입력할 수 있습니다.', 'error');
        return;
      }

      // 같은 입력이면 항상 같은 requestId — 실패 후 재시도가 워커 consume 멱등에 걸려 재차감되지 않는다.
      var zwRequestId = _cdAIPromptBuildRequestId('ziwei-ai-prompt', [
        _sajuPromptResolveProfileId(),
        question,
        chartResult,
        zwRequestEpoch
      ]);
      var zwReuse = zwEvidenceStore.get(zwRequestId);

      setLoading(true);
      setStatus(zwReuse
        ? '이미 확인된 결제 권한으로 추가 결제 없이 상담 답변을 다시 만들고 있습니다...'
        : '명반 데이터를 바탕으로 상담 답변을 작성하고 있습니다. 최대 1~2분 정도 걸릴 수 있어요...', 'info');

      function requestPromptWithEvidence(evidence) {
        return fetch('/api/fortune/ziwei/ai-prompt', {
          method: 'POST',
          credentials: 'include',
          headers: Object.assign(buildHeaders(), { 'idempotency-key': evidence.requestId || zwRequestId }),
          cache: 'no-store',
          body: JSON.stringify({
            question: question,
            chartResult: chartResult,
            requestId: evidence.requestId || zwRequestId,
            accessGrant: evidence.accessGrant,
            accessDecision: evidence.accessDecision,
            freeBySubscription: evidence.freeBySubscription,
            consume: evidence.consume,
            payment: evidence.payment,
            _paymentContext: evidence._paymentContext
          })
        }).then(function(res) {
          return res.json().catch(function() { return {}; }).then(function(payload) {
            return { ok: res.ok, status: res.status, payload: payload || {} };
          });
        });
      }

      // 실패 처리에서 이 증거를 보관해 재결제 없는 재시도를 열어 준다.
      function postWithEvidence(evidence) {
        return _cdRetryTransientPost(function() { return requestPromptWithEvidence(evidence); })
          .then(function(result) {
            if (result && typeof result === 'object') {
              result.requestId = zwRequestId;
              result._cdPaidEvidence = evidence;
            }
            return result;
          });
      }

      // 게이트(결제)는 1회만. 게이트 통과 후 생성 POST만 일시 503/네트워크 시 동일 requestId로 자동 재시도.
      var promptRequest = zwReuse
        ? postWithEvidence(zwReuse)
        : (paidPayload
          ? postWithEvidence(_cdAIPromptGateEvidence({
            ok: true,
            status: 200,
            payload: paidPayload,
            data: _cdAIPromptPayloadData(paidPayload),
            requestId: zwRequestId
          }))
          : _cdAIPromptGate({
            featureKey: _ZW_AI_PROMPT_FEATURE_KEY,
            reason: _ZW_AI_PROMPT_REASON,
            cost: _ZW_AI_PROMPT_COST,
            requestId: zwRequestId,
            categoryKey: 'ziwei'
          }).then(function(gateResult) {
            if (!gateResult.ok) return _cdAIPromptFailureResult(gateResult);
            return postWithEvidence(_cdAIPromptGateEvidence(gateResult));
          }));

      promptRequest.then(function(result) {
        var payload = result.payload || {};
        var resultText = String(payload.resultText || '').trim();
        var bonusPrompt = String(payload.generatedPrompt || payload.prompt || '').trim();
        if (result.ok && payload.ok === true && (resultText || bonusPrompt)) {
          if (resultText && answerEl) {
            answerEl.innerHTML = (window._cdRenderConsultAnswerHtml
              ? window._cdRenderConsultAnswerHtml(resultText)
              : '<p style="color:#ede9fe;white-space:pre-wrap;">' + resultText.replace(/[<>&]/g, '') + '</p>');
            answerEl.style.display = 'block';
            answerEl.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
          }
          // 프롬프트 무료 동봉 — 결과를 본 사용자에게 상담에 쓰인 프롬프트를 함께 제공.
          if (bonusPrompt) {
            outputEl.value = bonusPrompt;
            outputEl.scrollTop = 0;
            if (promptWrap) promptWrap.style.display = 'block';
            copyBtn.style.display = 'inline-flex';
          }
          regenerateBtn.style.display = 'inline-flex';
          // 성공했으므로 이 결제 증거는 소진됐다. epoch를 올려 같은 질문 재요청이 정상 결제로 가게 한다.
          zwEvidenceStore.clear();
          zwRetryFree = false;
          zwRequestEpoch += 1;
          var chargedCoins = Math.max(0, Number(payload.chargedCoins || 0));
          setStatus(
            chargedCoins > 0
              ? ('AI 상담이 완성되었습니다. ' + (chargedCoins * 100).toLocaleString('ko-KR') + '원 결제가 확인되었습니다.')
              : 'AI 상담이 완성되었습니다.',
            'success'
          );
          return;
        }

        var code = String(payload.code || '').trim();
        var message = String(payload.message || '').trim() || '프롬프트 생성 중 오류가 발생했습니다.';
        if (code === 'AUTH_REQUIRED' || result.status === 401 || result.status === 403) {
          zwEvidenceStore.clear();
          zwRetryFree = false;
          setStatus('로그인이 필요합니다. 로그인 페이지로 이동합니다.', 'error');
          setTimeout(function() {
            try {
              var next = getSajuEncodedReturnPath('saju-login-return-path');
              window.location.href = '/login?next=' + next;
            } catch (_) {}
          }, 700);
          return;
        }
        if (code === 'INSUFFICIENT_COINS' || result.status === 402) {
          zwEvidenceStore.clear();
          zwRetryFree = false;
          setStatus(message || '유료 결제가 필요합니다. 결제 페이지에서 상품을 선택해 주세요.', 'error');
          return;
        }
        // 결제는 확인됐는데 생성만 실패 — 서버가 환불하지 않았을 때만 증거를 보관해 무료 재시도를 연다.
        if (result && result._cdPaidEvidence && _cdAIPromptShouldRetainEvidence(payload)) {
          zwEvidenceStore.set(result.requestId, result._cdPaidEvidence);
          zwRetryFree = true;
          setStatus(message + _CD_AI_PROMPT_RETRY_HINT, 'error');
          return;
        }
        zwEvidenceStore.clear();
        zwRetryFree = false;
        setStatus(message, 'error');
      }).catch(function() {
        zwEvidenceStore.clear();
        zwRetryFree = false;
        setStatus('네트워크 오류가 발생했습니다. 잠시 후 다시 시도해 주세요.', 'error');
      }).finally(function() {
        setLoading(false);
      });
    }

    questionEl.addEventListener('input', function() {
      // 질문이 바뀌면 requestId 가 달라져 증거는 어차피 못 쓴다. 버튼 문구도 함께 되돌린다.
      if (zwRetryFree) {
        zwEvidenceStore.clear();
        zwRetryFree = false;
        if (!isLoading) setLoading(false);
      }
      updateCount();
      if (statusEl && statusEl.textContent) {
        setStatus('', 'info');
      }
    });

    generateBtn.addEventListener('click', handleGenerate);
    regenerateBtn.addEventListener('click', handleGenerate);

    copyBtn.addEventListener('click', function() {
      var text = String(outputEl.value || '').trim();
      if (!text) {
        setStatus('복사할 프롬프트가 없습니다.', 'error');
        return;
      }
      _zwCopyTextSafe(text).then(function() {
        setStatus('프롬프트를 복사했습니다. 원하는 AI에 붙여 넣어 사용하세요.', 'success');
      }).catch(function() {
        setStatus('복사에 실패했습니다. 텍스트를 직접 선택해 복사해 주세요.', 'error');
      });
    });

    updateCount();
    setStatus('질문 입력 후 버튼을 누르면 10,000원 결제 확인 후 상담 답변을 생성합니다.', 'info');
  }

  function _zwPortfolioBuildModalHtml(row, summary) {
    var mainText = row.mainStars.length ? row.mainStars.join(' · ') : '공궁(空宮)';
    var auxText = row.auxStars.length ? row.auxStars.join(' · ') : '보조성 없음';
    var badText = row.badStars.length ? row.badStars.join(' · ') : '흉성 영향 낮음';
    var keyTags = row.profile.keywords && row.profile.keywords.length ? row.profile.keywords : ['기질 파악', '패턴 분석'];
    var whyType = '주성 <span class="zwp-glow">' + _zwPortfolioEscapeHtml(mainText) + '</span> 조합은 <span class="zwp-glow">' + _zwPortfolioEscapeHtml(row.profile.type) + '</span> 성향을 강화합니다.';
    var evidence = _zwPortfolioEscapeHtml(row.profile.evidence || '해당 성계는 실전에서 판단-행동 간격을 좁히는 방향으로 작동합니다.');
    var relation = '이 궁은 전체 대표 타이틀 <span class="zwp-glow">' + _zwPortfolioEscapeHtml(summary.title) + '</span>과 연결되어, 현재 명반의 중심 테마를 구체 행동으로 변환하는 역할을 맡습니다.';
    var growthAction = {
      '권위형': ['중요 의사결정의 기준 3가지를 문장화하세요.', '팀 내 역할과 책임의 경계를 먼저 정의하세요.'],
      '권력형': ['협업 상대의 이해관계를 표로 정리해 충돌을 줄이세요.', '핵심 제안은 수치 근거 1개를 붙여 전달하세요.'],
      '관찰자': ['결정 전 24시간 관찰 규칙으로 성급한 판단을 줄이세요.', '핵심 가설을 1문장으로 축약해 실행팀과 공유하세요.'],
      '발산형': ['발표/브랜딩 채널을 1개 고정해 영향력을 축적하세요.', '주 1회 공개 기록으로 신뢰 자산을 쌓으세요.'],
      '실행형': ['우선순위 3개만 남기고 나머지는 보류 처리하세요.', '성과 지표를 주간 단위로 체크해 재투입 여부를 결정하세요.'],
      '수호형': ['리스크 목록과 대응 플랜을 미리 준비해 변동성을 낮추세요.', '핵심 자산은 보수적 분산으로 안정성을 확보하세요.'],
      '공감형': ['갈등 상황에서 사실/감정/요청을 분리해 대화하세요.', '에너지 소진을 막는 회복 루틴을 일정에 고정하세요.'],
      '매력형': ['네트워크 확장은 분기별 핵심 그룹 중심으로 진행하세요.', '유입된 기회는 수익성/지속성 기준으로 선별하세요.'],
      '논리형': ['반대 가설을 먼저 검증해 의사결정 오류를 줄이세요.', '핵심 문서는 체크리스트 기반으로 표준화하세요.'],
      '조율형': ['관계의 우선순위를 명확히 해 에너지 분산을 줄이세요.', '중재 시 양측의 공통 목표를 먼저 합의하세요.'],
      '보호형': ['장기 과제는 월 단위 리밸런싱으로 유지하세요.', '멘토링/후배 육성에 시간을 배정해 영향력을 확장하세요.']
    };
    var actions = growthAction[row.profile.type] || ['오늘 실행할 작은 행동 1개를 정하고 기록하세요.', '일주일 뒤 결과를 점검해 다음 행동으로 연결하세요.'];
    var actionHtml = '<ul class="zwp-modal-list"><li>' + _zwPortfolioEscapeHtml(actions[0]) + '</li><li>' + _zwPortfolioEscapeHtml(actions[1]) + '</li></ul>';

    return ''
      + '<p><b>[' + _zwPortfolioEscapeHtml(row.palaceDisplay) + ' · ' + _zwPortfolioEscapeHtml(row.branch) + '궁]</b> 성계 구성은 <span class="zwp-glow">' + _zwPortfolioEscapeHtml(row.profile.persona) + '</span> 축으로 읽힙니다.</p>'
      + '<div class="zwp-modal-tags">' + keyTags.map(function(tag){ return '<span class="zwp-modal-tag">#' + _zwPortfolioEscapeHtml(tag) + '</span>'; }).join('') + '</div>'
      + '<p>' + whyType + '</p>'
      + '<p>' + evidence + '</p>'
      + '<p><b>성계 근거:</b> 주성 ' + _zwPortfolioEscapeHtml(mainText) + ' / 보조성 ' + _zwPortfolioEscapeHtml(auxText) + ' / 경계성 ' + _zwPortfolioEscapeHtml(badText) + '</p>'
      + '<p>' + relation + '</p>'
      + '<p><b>실전 실행 가이드</b></p>'
      + actionHtml
      + '<div class="zwp-swipe-hint">아래로 스와이프하거나 ✶ 버튼으로 닫을 수 있습니다.</div>';
  }

  for(let i=0; i<12; i++) {
    let pName = palace.palacesByIndex[i]; // 명궁, 형제궁..
    let pZhi = ZHI_LIST[i];
    let pGan = palace.gongGan[pZhi];
    let st = palace.stars[i] || { main: [], borrowedMain: [], aux: [], bad: [] };
    let mainList = (st.main && st.main.length) ? st.main : (st.borrowedMain || []);

    let dName = pName;
    let cellTags = '';
    if (pZhi === palace.meng) cellTags += '<span class="zw-tag zw-tag-meng">명궁</span>';
    if (pZhi === palace.shen) cellTags += '<span class="zw-tag zw-tag-shen">신궁</span>';
    let mergedStarRaw = mainList.concat(st.aux || [], st.bad || []);
    let sihuaCell = '';
    for (let m = 0; m < mergedStarRaw.length; m++) {
      let rawStar = String(mergedStarRaw[m] || '');
      let sihuaMatch = rawStar.match(/화록|화권|화과|화기/);
      if (sihuaMatch) {
        sihuaCell = sihuaMatch[0];
        break;
      }
    }
    if (sihuaCell) {
      let sihuaClass = sihuaCell === '화기' ? 'zw-tag-hwa-gi'
        : sihuaCell === '화록' ? 'zw-tag-hwa-lu'
        : sihuaCell === '화권' ? 'zw-tag-hwa-quan'
        : sihuaCell === '화과' ? 'zw-tag-hwa-ke'
        : 'zw-tag-hwa-good';
      cellTags += '<span class="zw-tag ' + sihuaClass + '">' + sihuaCell + '</span>';
    }
    let palacePower = 30 + (mainList.length * 17) + ((st.aux || []).length * 5) - ((st.bad || []).length * 3);
    if (sihuaCell) palacePower += sihuaCell === '화기' ? 4 : 10;
    if (pZhi === palace.meng) palacePower += 18;
    if (pZhi === palace.shen) palacePower += 12;
    palacePower = Math.max(24, Math.min(96, palacePower));
    let palacePowerClass = palacePower >= 72 ? 'zw-cell-power-high' : (palacePower >= 52 ? 'zw-cell-power-mid' : 'zw-cell-power-low');
    let roleClass = (pZhi === palace.meng ? ' zw-cell-meng' : '') + (pZhi === palace.shen ? ' zw-cell-shen' : '');
    let glowColor = sihuaCell === '화기'
      ? 'rgba(248,113,113,0.42)'
      : (pZhi === palace.meng ? 'rgba(250,204,21,0.5)' : (pZhi === palace.shen ? 'rgba(125,211,252,0.46)' : 'rgba(196,181,253,0.34)'));
    let cellStyle = '--zw-cell-score:' + palacePower + ';--zw-cell-glow:' + glowColor + '; animation-delay: '+(i*0.06)+'s;';

    html += '<div class="zw-cell zw-cell-'+i+' '+palacePowerClass+roleClass+'" role="button" tabindex="0" aria-label="' + dName + ' ' + _sajuEngineText("se_18017_attr_aria_label") + ', ' + palacePower + _sajuEngineText("se_18017_attr_aria_label_score_suffix") + '" style="'+cellStyle+'" onclick="window._handleZwClick('+i+', this)">';
    html += '<div class="zw-cell-aura" aria-hidden="true"></div>';
    html += '<div class="zw-palace-starlane" aria-hidden="true"></div>';
    html += '<div class="zw-palace-name">' + dName + '</div>';
    if (cellTags) html += '<div class="zw-tag-layer">' + cellTags + '</div>';
    html += '<div class="zw-stars-wrap star-list">';
    if(mainList.length > 0) {
      mainList.forEach(function(s){
        var rendered = _zwRenderMainStar(s, pZhi);
        html += '<div class="zw-star-main">' + (rendered || s) + '</div>';
      });
    } else {
      html += '<div class="zw-empty">공궁(空宮)</div>';
    }
    if(st.aux.length > 0) {
      let auxStr = st.aux.map(function(s){ return _zwRenderMinorStar(s, pZhi); }).join(' ');
      html += '<div class="zw-star-aux">'+auxStr+'</div>';
    }
    if(st.bad.length > 0) {
      let badStr = st.bad.map(function(s){ return _zwRenderMinorStar(s, pZhi); }).join(' ');
      html += '<div class="zw-star-bad">'+badStr+'</div>';
    }
    html += '</div>';

    let dAge = (palace.daHan && palace.daHan[i]) ? palace.daHan[i] : '';
    if(dAge) html += '<div class="zw-dahan">' + dAge + '</div>';

    html += '<div class="zw-palace-gan">' + pGan + '</div>';
    html += '<div class="zw-branch-name">' + pZhi + '</div>';
    html += '</div>';
  }

  html += '<div class="zw-center-panel">';
