        if (annualAnchorIdx < 0 && pd.palacesByIndex) annualAnchorIdx = pd.palacesByIndex.indexOf('명궁');
        if (annualAnchorIdx < 0) annualAnchorIdx = 0;
        var monthlyFlowHtml = '';
